+// CommitSourceActivityDay is one source's share of a UTC day's default-branch
+// commits. Source is a canonical known agent, "unknown" for a checkpoint-linked
+// commit without a known payload agent, or "manual" for an unlinked commit.
+type CommitSourceActivityDay struct {
+	Date   time.Time
+	Source string
+	Count  int
+}
+
+// CommitSourceActivity is the repo-overview commit-source rollup. Total is the
+// authoritative repo_author_day commit total; Daily partitions every included
+// commit exactly once among known-agent, unknown, and manual source cells.
+type CommitSourceActivity struct {
+	Total int
+	Daily []CommitSourceActivityDay
+}
+
+// CommitSourceActivity computes the default-branch commit-source rollup for a
+// code repo, resolving checkpoint payloads from storageRepoID. The commit axis is
+// repo_author_day, while shipped checkpoint links provide per-commit source hints.
+// A commit linked to multiple checkpoints chooses the lexical known agent after
+// dropping blank and literal "unknown" values; if none remains, it is unknown.
+// Linked commits are SHA-ranked and capped at each day's rollup total so transient
+// payload/link hydration skew cannot make the source partition exceed the rollup.
+func (s *RepoStore) CommitSourceActivity(ctx context.Context, repoID, storageRepoID string, since, until *time.Time) (CommitSourceActivity, error) {
+	id, err := ulidBytes(repoID)
+	if err != nil {
+		return CommitSourceActivity{}, fmt.Errorf("store: commit source activity: %w", err)
+	}
+	storageID, err := ulidBytes(storageRepoID)
+	if err != nil {
+		return CommitSourceActivity{}, fmt.Errorf("store: commit source activity storage repo: %w", err)
+	}
+
+	baseArgs := []any{id, storageID}
+	radWin, args := dayWindowClause("rad.day", since, until, baseArgs)
+	ccWin, _ := dayWindowClause("(cc.commit_date AT TIME ZONE 'UTC')::date", since, until, baseArgs)
+	q := `WITH day_commits AS (
+  SELECT rad.day, sum(rad.commits) AS count
+  FROM repo_author_day rad
+  WHERE rad.repo_id = $1 AND rad.commits > 0` + radWin + `
+  GROUP BY rad.day
+),
+per_commit AS (
+  SELECT (cc.commit_date AT TIME ZONE 'UTC')::date AS day, cc.commit_sha,
+    coalesce(min(nullif(nullif(k.primary_agent, ''), 'unknown')), 'unknown') AS source
+  FROM checkpoint_commits cc
+  LEFT JOIN checkpoints k ON k.repo_id = $2 AND k.checkpoint_id = cc.checkpoint_id
+  WHERE cc.repo_id = $1 AND cc.commit_state = 'shipped'` + ccWin + `
+  GROUP BY 1, cc.commit_sha
+),
+ranked AS (
+  SELECT pc.*, row_number() OVER (PARTITION BY pc.day ORDER BY pc.commit_sha) AS sha_rank
+  FROM per_commit pc
+),
+retained AS (
+  SELECT r.day, r.commit_sha, r.source
+  FROM ranked r
+  JOIN day_commits dc ON dc.day = r.day AND r.sha_rank <= dc.count
+),
+activity AS (
+  SELECT r.day, r.source, count(*) AS count
+  FROM retained r
+  GROUP BY r.day, r.source
+  UNION ALL
+  SELECT dc.day, 'manual' AS source, dc.count - count(r.commit_sha) AS count
+  FROM day_commits dc
+  LEFT JOIN retained r ON r.day = dc.day
+  GROUP BY dc.day, dc.count
+  HAVING dc.count - count(r.commit_sha) > 0
+)
+SELECT day, source, count
+FROM activity
+ORDER BY day, source`
+	rows, err := s.pool.Query(ctx, q, args...)
+	if err != nil {
+		return CommitSourceActivity{}, fmt.Errorf("store: commit source activity: %w", err)
+	}
+	defer rows.Close()
+
+	out := CommitSourceActivity{Daily: []CommitSourceActivityDay{}}
+	for rows.Next() {
+		var cell CommitSourceActivityDay
+		if err := rows.Scan(&cell.Date, &cell.Source, &cell.Count); err != nil {
+			return CommitSourceActivity{}, fmt.Errorf("store: commit source activity scan: %w", err)
+		}
+		cell.Date = cell.Date.UTC()
+		out.Total += cell.Count
+		out.Daily = append(out.Daily, cell)
+	}
+	if err := rows.Err(); err != nil {
+		return CommitSourceActivity{}, fmt.Errorf("store: commit source activity: %w", err)
+	}
+	return out, nil
+}
