+func mergeSessionSubagentSources(
+	legacy []store.SubagentSummary,
+	discovered []readthroughSubagent,
+	afterStarted time.Time,
+	afterID string,
+) []store.SubagentSummary {
+	rows := append([]store.SubagentSummary(nil), legacy...)
+	legacyTools := make(map[string]struct{}, len(legacy))
+	legacySources := make(map[string]struct{}, len(legacy))
+	for _, child := range legacy {
+		if child.ToolUseID != nil {
+			legacyTools[*child.ToolUseID] = struct{}{}
+		}
+		if child.SourceTaskID != "" {
+			legacySources[child.SourceTaskID] = struct{}{}
+		}
+	}
+	for _, child := range discovered {
+		if child.Summary.ToolUseID != nil {
+			if _, exists := legacyTools[*child.Summary.ToolUseID]; exists {
+				continue
+			}
+		}
+		if child.Summary.SourceTaskID != "" {
+			if _, exists := legacySources[child.Summary.SourceTaskID]; exists {
+				continue
+			}
+		}
+		rows = append(rows, child.Summary)
+	}
+	rows = filterSubagentsAfterCursor(rows, afterStarted, afterID)
+	sort.SliceStable(rows, func(i, j int) bool {
+		if rows[i].StartedAt.Equal(rows[j].StartedAt) {
+			return rows[i].SubagentID < rows[j].SubagentID
+		}
+		return rows[i].StartedAt.Before(rows[j].StartedAt)
+	})
+	return rows
+}
+
+func filterSubagentsAfterCursor(rows []store.SubagentSummary, afterStarted time.Time, afterID string) []store.SubagentSummary {
+	if afterID == "" {
+		return rows
+	}
+	out := rows[:0]
+	for _, row := range rows {
+		if row.StartedAt.After(afterStarted) || (row.StartedAt.Equal(afterStarted) && row.SubagentID > afterID) {
+			out = append(out, row)
+		}
+	}
