+func resolveReadthroughSubagent(
+	ctx context.Context,
+	deps *RepoActivityDeps,
+	codeRepoID, storageRepoID, parentID, subagentID string,
+	checkpoints []store.ContributingCheckpointSessions,
+) (readthroughSubagent, bool, error) {
+	if len(checkpoints) == 0 || !safeTaskSegment(subagentID) {
+		return readthroughSubagent{}, false, nil
+	}
+	client, parentToolIDs, err := readthroughClientAndToolIDs(
+		ctx, deps, codeRepoID, storageRepoID, parentID, checkpoints,
