+	)
+	if err != nil {
+		return readthroughSubagent{}, false, err
+	}
+	if err := redactTaskDescriptions(ctx, contributions); err != nil {
+		return readthroughSubagent{}, false, err
+	}
+	children := mergeReadthroughSubagents(contributions)
+	if len(children) == 0 {
+		return readthroughSubagent{}, false, nil
+	}
+	return children[0], true, nil
