+
+func readthroughClientAndToolIDs(
+	ctx context.Context,
+	deps *RepoActivityDeps,
+	codeRepoID, storageRepoID, parentID string,
+	checkpoints []store.ContributingCheckpointSessions,
+) (*repoapi.Client, map[string]string, error) {
+	if deps.RepoAPIBase == "" {
+		return nil, nil, errors.New("RepoAPIBase empty")
+	}
+	readCtx, err := deps.storageReadContext(ctx, codeRepoID, storageRepoID)
+	if err != nil {
+		return nil, nil, err
+	}
+	client := repoContentClient(readCtx, deps)
+
+	var parentToolIDs map[string]string
+	if needsParentToolAssociation(checkpoints) {
+		parent, readFailed, mergeErr := mergeSessionTranscript(ctx, deps.TranscriptBudget, codeRepoID, parentID, checkpoints,
+			func(readContext context.Context, checkpoint store.ContributingCheckpointSessions, idx int) ([]byte, error) {
+				ref, folder := checkpointlayout.RefAndFolder(checkpoint.CheckpointID, checkpoint.RefBacked)
+				return client.RawFile(readContext, deps.RepoAPIBase, storageRepoID, ref,
+					store.SessionBlobPathAt(checkpoint.Sessions, folder, idx), checkpointlayout.MaxTranscriptBytes)
+			})
+		if mergeErr != nil {
+			return nil, nil, mergeErr
+		}
+		parentToolIDs, err = parentTranscriptAssociationIDs(parent, readFailed, parentToolAssociationRequired(checkpoints))
+		if err != nil {
+			return nil, nil, err
+		}
+	}
+	return client, parentToolIDs, nil
+}
+
+func needsParentToolAssociation(checkpoints []store.ContributingCheckpointSessions) bool {
+	return len(checkpoints) > 0
+}
+
+func parentToolAssociationRequired(checkpoints []store.ContributingCheckpointSessions) bool {
+	for _, checkpoint := range checkpoints {
+		if len(checkpoint.Sessions) > 1 {
+			return true
+		}
+	}
+	return false
+}
+
+func parentTranscriptAssociationIDs(parent transcript.SessionTranscript, readFailed, required bool) (map[string]string, error) {
+	if readFailed && len(parent.Messages) == 0 {
+		if required {
+			return nil, errors.New("parent session transcript unavailable")
+		}
+		return nil, nil
+	}
+	return transcriptAssociationCallIDs(parent.Messages), nil
+}
+
+func transcriptAssociationCallIDs(messages []transcript.TranscriptMessage) map[string]string {
+	associations := make(map[string]string)
+	directCallIDs := make(map[string]struct{})
+	for _, message := range messages {
+		for _, call := range message.ToolCalls {
+			if call.ID != "" {
+				associations[call.ID] = call.ID
+				directCallIDs[call.ID] = struct{}{}
+			}
+		}
+	}
+	for _, message := range messages {
+		for _, call := range message.ToolCalls {
+			if call.ID == "" {
+				continue
+			}
+			if call.Result != nil {
+				resultIDs := make(map[string]struct{})
+				collectTranscriptResultAssociationIDs(call.Result.Output, resultIDs)
+				for id := range resultIDs {
+					if _, direct := directCallIDs[id]; direct {
+						continue
+					}
+					if existing, seen := associations[id]; seen && existing != call.ID {
+						associations[id] = ""
+						continue
+					}
+					associations[id] = call.ID
+				}
+			}
+		}
+	}
+	return associations
+}
+
+func collectTranscriptResultAssociationIDs(output string, ids map[string]struct{}) {
+	var value any
+	if json.Unmarshal([]byte(output), &value) != nil {
+		return
+	}
+	var walk func(any)
+	walk = func(value any) {
+		switch value := value.(type) {
+		case map[string]any:
+			for key, child := range value {
+				switch key {
+				case "agent_id", "agentId", "subagent_id", "subagentId", "thread_id", "threadId":
+					if id, ok := child.(string); ok && safeTaskSegment(id) {
+						ids[id] = struct{}{}
+					}
+				}
+				walk(child)
+			}
+		case []any:
+			for _, child := range value {
+				walk(child)
+			}
+		}
+	}
+	walk(value)
+}
