+			len(checkpoints), subagentMaxContributingCheckpoints, repoapi.ErrWalkTruncated)
+	}
+	return readCheckpointTaskContributionsConcurrent(ctx, checkpoints,
+		func(readCtx context.Context, checkpoint store.ContributingCheckpointSessions) ([]readthroughTaskContribution, error) {
+			return readCheckpointTask(readCtx, reader, base, repoID, parentID, parentToolIDs, taskID, checkpoint)
+		})
+}
+
+func readCheckpointTaskContributionsConcurrent(
+	ctx context.Context,
+	checkpoints []store.ContributingCheckpointSessions,
+	read func(context.Context, store.ContributingCheckpointSessions) ([]readthroughTaskContribution, error),
+) ([]readthroughTaskContribution, error) {
+	results := make([][]readthroughTaskContribution, len(checkpoints))
+	errs := make([]error, len(checkpoints))
+	var group errgroup.Group
+	group.SetLimit(subagentCheckpointReadConcurrency)
+	for i, checkpoint := range checkpoints {
+		group.Go(func() error {
+			results[i], errs[i] = read(ctx, checkpoint)
+			return nil
+		})
+	}
+	_ = group.Wait()
+	var contributions []readthroughTaskContribution
+	var failures []error
+	for i, checkpointContributions := range results {
+		if errs[i] != nil {
+			failures = append(failures, errs[i])
+			continue
+		}
+		contributions = append(contributions, checkpointContributions...)
+	}
+	for _, err := range failures {
+		if errors.Is(err, repoapi.ErrWalkTruncated) {
+			return nil, err
+		}
+	}
+	if len(failures) == len(checkpoints) && len(failures) > 0 {
+		return nil, errors.Join(failures...)
+	}
+	if len(failures) > 0 {
+		slog.WarnContext(ctx, "subagent checkpoint artifact reads partially failed",
+			"checkpoint_count", len(checkpoints), "failed_count", len(failures))
+	}
+	return contributions, nil
+}
