+type subagentTaskReadBudget struct {
+	metadataFiles atomic.Int64
+}
+
+func (b *subagentTaskReadBudget) reserve(count int) bool {
+	for {
+		used := b.metadataFiles.Load()
+		if int64(count) > int64(subagentMaxTaskMetadataFiles)-used {
+			return false
+		}
+		if b.metadataFiles.CompareAndSwap(used, used+int64(count)) {
+			return true
+		}
+	}
+}
