598	+func transcriptAssociationCallIDs(messages []transcript.TranscriptMessage) map[string]string {
599	+	associations := make(map[string]string)
600	+	directCallIDs := make(map[string]struct{})
601	+	for _, message := range messages {
602	+		for _, call := range message.ToolCalls {
603	+			if call.ID != "" {
604	+				associations[call.ID] = call.ID
605	+				directCallIDs[call.ID] = struct{}{}
606	+			}
607	+		}
608	+	}
609	+	for _, message := range messages {
610	+		for _, call := range message.ToolCalls {
611	+			if call.ID == "" {
612	+				continue
613	+			}
614	+			if call.Result != nil {
615	+				resultIDs := make(map[string]struct{})
616	+				collectTranscriptResultAssociationIDs(call.Result.Output, resultIDs)
617	+				for id := range resultIDs {
618	+					if _, direct := directCallIDs[id]; direct {
619	+						continue
620	+					}
621	+					if existing, seen := associations[id]; seen && existing != call.ID {
622	+						associations[id] = ""
623	+						continue
624	+					}
625	+					associations[id] = call.ID
626	+				}
627	+			}
628	+		}
629	+	}
630	+	return associations
631	+}
632	+
633	+func collectTranscriptResultAssociationIDs(output string, ids map[string]struct{}) {
634	+	var value any
635	+	if json.Unmarshal([]byte(output), &value) != nil {
636	+		return
637	+	}
638	+	var walk func(any)
639	+	walk = func(value any) {
640	+		switch value := value.(type) {
641	+		case map[string]any:
642	+			for key, child := range value {
643	+				switch key {
644	+				case "agent_id", "agentId", "subagent_id", "subagentId", "thread_id", "threadId":
645	+					if id, ok := child.(string); ok && safeTaskSegment(id) {
646	+						ids[id] = struct{}{}
647	+					}
648	+				}
649	+				walk(child)
650	+			}
651	+		case []any:
652	+			for _, child := range value {
653	+				walk(child)
654	+			}
655	+		}
656	+	}
657	+	walk(value)
658	+}
