713	+func readCheckpointTaskContributionsConcurrent(
714	+	ctx context.Context,
715	+	checkpoints []store.ContributingCheckpointSessions,
716	+	read func(context.Context, store.ContributingCheckpointSessions) ([]readthroughTaskContribution, error),
717	+) ([]readthroughTaskContribution, error) {
718	+	results := make([][]readthroughTaskContribution, len(checkpoints))
719	+	errs := make([]error, len(checkpoints))
720	+	var group errgroup.Group
721	+	group.SetLimit(subagentCheckpointReadConcurrency)
722	+	for i, checkpoint := range checkpoints {
723	+		group.Go(func() error {
724	+			results[i], errs[i] = read(ctx, checkpoint)
725	+			return nil
726	+		})
727	+	}
728	+	_ = group.Wait()
729	+	var contributions []readthroughTaskContribution
730	+	var failures []error
731	+	for i, checkpointContributions := range results {
732	+		if errs[i] != nil {
733	+			failures = append(failures, errs[i])
734	+			continue
735	+		}
736	+		contributions = append(contributions, checkpointContributions...)
737	+	}
738	+	for _, err := range failures {
739	+		if errors.Is(err, repoapi.ErrWalkTruncated) {
740	+			return nil, err
741	+		}
742	+	}
743	+	if len(failures) == len(checkpoints) && len(failures) > 0 {
744	+		return nil, errors.Join(failures...)
745	+	}
746	+	if len(failures) > 0 {
747	+		slog.WarnContext(ctx, "subagent checkpoint artifact reads partially failed",
748	+			"checkpoint_count", len(checkpoints), "failed_count", len(failures))
749	+	}
750	+	return contributions, nil
751	+}
