780	+func readCheckpointTasks(
781	+	ctx context.Context,
782	+	reader subagentArtifactReader,
783	+	base, repoID, parentID string,
784	+	parentToolIDs map[string]string,
785	+	checkpoint store.ContributingCheckpointSessions,
786	+	budget *subagentTaskReadBudget,
787	+) ([]readthroughTaskContribution, error) {
788	+	ref, folder := checkpointlayout.RefAndFolder(checkpoint.CheckpointID, checkpoint.RefBacked)
789	+	tasksRoot := checkpointlayout.TasksPath(folder)
790	+	entries, truncated, err := reader.Tree(ctx, base, repoID, ref, tasksRoot, true)
791	+	if errors.Is(err, repoapi.ErrNotFound) {
792	+		return nil, nil
793	+	}
794	+	if err != nil {
795	+		return nil, fmt.Errorf("read subagent task tree %s: %w", checkpoint.CheckpointID, err)
796	+	}
797	+	if truncated || len(entries) > checkpointlayout.MaxTaskEntries {
798	+		return nil, fmt.Errorf("read subagent task tree %s: %w", checkpoint.CheckpointID, repoapi.ErrWalkTruncated)
799	+	}
800	+
801	+	blobs := make(map[string]struct{}, len(entries))
802	+	var metadataPaths []string
803	+	for _, entry := range entries {
804	+		if entry.Type != "blob" {
805	+			continue
806	+		}
807	+		entryPath, ok := normalizeTaskEntryPath(tasksRoot, entry.Path)
808	+		if !ok {
809	+			continue
810	+		}
811	+		if _, duplicate := blobs[entryPath]; duplicate {
812	+			continue
813	+		}
814	+		blobs[entryPath] = struct{}{}
815	+		if isTaskMetadataPath(tasksRoot, entryPath) {
816	+			metadataPaths = append(metadataPaths, entryPath)
817	+		}
818	+	}
819	+	if len(metadataPaths) == 0 {
820	+		return nil, nil
821	+	}
822	+	if !budget.reserve(len(metadataPaths)) {
823	+		return nil, fmt.Errorf("read subagent task metadata %s: %w", checkpoint.CheckpointID, repoapi.ErrWalkTruncated)
824	+	}
825	+	sort.Strings(metadataPaths)
826	+	files, err := reader.Files(ctx, base, repoID, ref, metadataPaths, subagentMaxTaskMetadataBytes)
827	+	if err != nil {
828	+		return nil, fmt.Errorf("read subagent task metadata %s: %w", checkpoint.CheckpointID, err)
829	+	}
830	+	contributions := make([]readthroughTaskContribution, 0, len(metadataPaths))
831	+	for _, metadataPath := range metadataPaths {
832	+		if contribution, ok := taskContributionFromMetadata(
833	+			metadataPath, files[metadataPath], blobs, parentID, parentToolIDs, checkpoint,
834	+		); ok {
835	+			contributions = append(contributions, contribution)
836	+		}
837	+	}
838	+	return contributions, nil
839	+}
