841	+func taskContributionFromMetadata(
842	+	metadataPath string,
843	+	file repoapi.FileResult,
844	+	blobs map[string]struct{},
845	+	parentID string,
846	+	parentToolIDs map[string]string,
847	+	checkpoint store.ContributingCheckpointSessions,
848	+) (readthroughTaskContribution, bool) {
849	+	if file.Status != repoapi.FileStatusOK || file.Size > int64(len(file.Content)) {
850	+		return readthroughTaskContribution{}, false
851	+	}
852	+	var metadata taskArtifactMetadata
853	+	if json.Unmarshal(file.Content, &metadata) != nil {
854	+		return readthroughTaskContribution{}, false
855	+	}
856	+	taskDirID := path.Base(path.Dir(metadataPath))
857	+	agentIDValid := safeTaskSegment(metadata.AgentID) ||
858	+		(metadata.AgentID == "" && metadata.TranscriptUnavailableReason != "")
859	+	if metadata.ToolUseID != taskDirID || metadata.StartedAt.IsZero() || !safeTaskSegment(metadata.ToolUseID) || !agentIDValid ||
860	+		!taskBelongsToSession(parentID, checkpoint.Sessions, parentToolIDs, metadata.ToolUseID) {
861	+		return readthroughTaskContribution{}, false
862	+	}
863	+	capturedAt := metadata.StartedAt
864	+	if checkpoint.CreatedAt != nil {
865	+		capturedAt = *checkpoint.CreatedAt
866	+	}
867	+	transcriptPath := ""
868	+	if metadata.AgentID != "" && metadata.TranscriptUnavailableReason == "" {
869	+		transcriptPath = path.Join(path.Dir(metadataPath), "agent-"+metadata.AgentID+".jsonl")
870	+	}
871	+	if blobs != nil && transcriptPath != "" {
872	+		if _, ok := blobs[transcriptPath]; !ok {
873	+			transcriptPath = ""
874	+		}
875	+	}
876	+	return readthroughTaskContribution{
877	+		ToolUseID: metadata.ToolUseID, ParentToolUseID: parentToolIDs[metadata.ToolUseID], AgentID: metadata.AgentID,
878	+		Agent:           checkpointSessionAgent(checkpoint.Sessions, parentID),
879	+		TaskDescription: metadata.TaskDescription, StartedAt: metadata.StartedAt,
880	+		CheckpointID: checkpoint.CheckpointID, CapturedAt: capturedAt,
881	+		TranscriptPath: transcriptPath, RefBacked: checkpoint.RefBacked,
882	+	}, true
883	+}
