894	+func normalizeTaskEntryPath(tasksRoot, value string) (string, bool) {
895	+	if value == "" || strings.HasPrefix(value, "/") {
896	+		return "", false
897	+	}
898	+	for _, segment := range strings.Split(value, "/") {
899	+		if segment == "." || segment == ".." {
900	+			return "", false
901	+		}
902	+	}
903	+	cleaned := path.Clean(value)
904	+	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
905	+		return "", false
906	+	}
907	+	if cleaned != tasksRoot && !strings.HasPrefix(cleaned, tasksRoot+"/") {
908	+		cleaned = path.Join(tasksRoot, cleaned)
909	+	}
910	+	return cleaned, strings.HasPrefix(cleaned, tasksRoot+"/")
911	+}
