package store

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

const (
	defaultSessionSubagentLimit = 50
	maxSessionSubagentLimit     = 200
)

// SubagentSummary is one logical child in a parent session. SourceTaskID is an
// internal normalization key and is never exposed on the HTTP wire.
type SubagentSummary struct {
	SubagentID      string
	SourceTaskID    string
	ToolUseID       *string
	Agent           string
	NativeAgentID   *string
	TaskDescription string
	StartedAt       time.Time
	LastActivityAt  time.Time
	CheckpointCount int64
}

// ContributingSubagentTranscript locates one captured transcript candidate.
type ContributingSubagentTranscript struct {
	CheckpointID   string
	CapturedAt     time.Time
	TranscriptPath string
	RefBacked      bool
	DecoderVersion int16
}

// ListSessionSubagents returns logical children in stable
// (started_at, subagent_id) order from rows captured before the rollback.
func (s *RepoStore) ListSessionSubagents(ctx context.Context, repoID, parentID string, afterStarted time.Time, afterID string, limit int) ([]SubagentSummary, bool, error) {
	rid, err := ulidBytes(repoID)
	if err != nil {
		return nil, false, fmt.Errorf("store: list session subagents %s/%s: %w", repoID, parentID, err)
	}
	if strings.TrimSpace(parentID) == "" {
		return nil, false, errors.New("store: list session subagents: empty parent session id")
	}
	if (afterID == "") != afterStarted.IsZero() {
		return nil, false, errors.New("store: list session subagents: incomplete cursor")
	}
	if limit <= 0 {
		limit = defaultSessionSubagentLimit
	}
	if limit > maxSessionSubagentLimit {
		limit = maxSessionSubagentLimit
	}

	args := []any{rid, parentID}
	keyset := ""
	if afterID != "" {
		args = append(args, afterStarted, afterID)
		keyset = "WHERE (a.started_at, l.subagent_id) > ($3, $4)"
	}
	args = append(args, limit+1)
	query := fmt.Sprintf(`
		WITH aggregated AS (
			SELECT agent, source_task_id, min(started_at) AS started_at,
			       max(captured_at) AS last_activity_at,
			       count(DISTINCT checkpoint_id) AS checkpoint_count
			FROM checkpoint_subagents
			WHERE repo_id = $1 AND parent_session_id = $2
			GROUP BY agent, source_task_id
		), latest AS (
			SELECT DISTINCT ON (agent, source_task_id)
			       agent, source_task_id, subagent_id, tool_use_id, native_agent_id, task_description
			FROM checkpoint_subagents
			WHERE repo_id = $1 AND parent_session_id = $2
			ORDER BY agent, source_task_id, captured_at DESC, checkpoint_id DESC
		)
		SELECT l.subagent_id, l.source_task_id, l.tool_use_id, l.agent, l.native_agent_id,
		       l.task_description, a.started_at, a.last_activity_at, a.checkpoint_count
		FROM aggregated a
		JOIN latest l USING (agent, source_task_id)
		%s
		ORDER BY a.started_at, l.subagent_id
		LIMIT $%d`, keyset, len(args))
	rows, err := s.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, false, fmt.Errorf("store: list session subagents %s/%s: %w", repoID, parentID, err)
	}
	defer rows.Close()
	out, err := pgx.CollectRows(rows, func(row pgx.CollectableRow) (SubagentSummary, error) {
		var summary SubagentSummary
		err := row.Scan(&summary.SubagentID, &summary.SourceTaskID, &summary.ToolUseID, &summary.Agent,
			&summary.NativeAgentID, &summary.TaskDescription, &summary.StartedAt, &summary.LastActivityAt,
			&summary.CheckpointCount)
		return summary, err
	})
	if err != nil {
		return nil, false, fmt.Errorf("store: list session subagents %s/%s: scan: %w", repoID, parentID, err)
	}
	if len(out) > limit {
		return out[:limit], true, nil
	}
	return out, false, nil
}

