// session sharing for authenticated members and anonymous share-link viewers
// alike — including shared sessions in private repos. There is no legacy-database
// fallback.
repoRoutes.get(
  "/:org/:repo/session/:sessionId/transcript",
  optionalAuth,
  rateLimitUnauthenticated,
  async (c) => {
    const userId = c.get("userId") as string | undefined

    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const sessionId = requiredParam(c, "sessionId")
    const requestedProvider = c.req.query("provider")
    const provider = isRepoSlugProvider(requestedProvider) ? requestedProvider : undefined

    if (!SESSION_ID_PATTERN.test(sessionId)) {
      return c.json({ error: "Invalid session ID format" }, 400)
    }

    const proxyParams = {
      owner: org,
      repo,
      userId,
      repoProvider: provider,
      pathFor: (id: string) => `repos/${id}/sessions/${sessionId}/transcript`,
    }

    // entire-api's public-repo path serves anonymous callers (public repos and
    // shared sessions, including shared sessions in private repos); a session
    // that is not shared or not visible folds to a normalized 404, with no local
    // fallback. Authenticated members are served via their session.
    const proxied = await proxyEntireApiRead(c, proxyParams)
    if (!userId) return proxied

    // Surface the repo's home cell on the envelope so the share dialog can build
    // the dedicated /sessions/:cell/:shareId link on load — an authed-only
    // concern (anonymous viewers have no share dialog).
    return attachHomeCellToTranscript(c, proxied, {
      owner: org,
      repo,
      provider,
    })
  },
)

