func transcriptForSession(ctx context.Context, deps *RepoActivityDeps, in *SessionTranscriptInput) (*SessionTranscriptOutput, error) {
	// The checkpoint payload + live blobs live in the storage repo (resolved from
	// the code repo); the envelope (repo/session/checkpoints/viewer) and the
	// public-share/snapshot state stay keyed to the code repo. Resolve-only (no
	// hard gate) here: this route is optional-auth, so member-ness is decided by
	// callerRepoReadAccess on the storage repo (the bytes' home), and a non-member
	// may still read a shared snapshot.
	storageRepoID, err := deps.Store.CheckpointStorageRepoID(ctx, in.RepoID)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: resolve checkpoint storage repo", err)
	}
	// Resolve the byte source (and the isPublic flag) before touching the session,
	// so a caller with neither storage-repo access nor a readable share gets 404
	// without learning whether the session exists. A repo-absent (404) / SpiceDB
	// (503) / store (500) failure for an authenticated caller surfaces here rather
	// than degrading them to the snapshot branch.
	member, err := callerRepoReadAccess(ctx, deps, storageRepoID)
	if err != nil {
		return nil, err
	}
	src, isPublic, err := sessionBlobSource(ctx, deps, storageRepoID, in.RepoID, in.SessionID, member)
	if err != nil {
		return nil, err
	}
	return buildSessionTranscript(ctx, deps, in.RepoID, storageRepoID, in.SessionID, src, isPublic)
}

func mergeSessionTranscript(ctx context.Context, budget *transcript.Budget, repoID, sessionID string, contribs []store.ContributingCheckpointSessions, src rawBlobSource) (transcript.SessionTranscript, bool, error) {
	var readFailed bool
	// noteBlobReadErr records a src() failure. errSnapshotMissingCheckpoint is an
	// EXPECTED, tolerated miss — a shared-viewer snapshot bundle lagging the live
	// contributing set, which is exactly why the reads fall back to older copies —
	// so it logs at debug and does NOT flag readFailed (a healthy shared read must
	// not surface "failed" or emit a false ERROR alarm). Any other error is a
	// genuine read failure: ERROR-logged and readFailed=true.
	noteBlobReadErr := func(checkpointID string, err error) {
		if errors.Is(err, errSnapshotMissingCheckpoint) {
			slog.DebugContext(ctx, "transcript: snapshot missing checkpoint (tolerated)",
				"repo_id", repoID, "session_id", sessionID, "checkpoint_id", checkpointID)
			return
		}
		readFailed = true
		slog.ErrorContext(ctx, "transcript: blob read failed",
			"repo_id", repoID, "session_id", sessionID, "checkpoint_id", checkpointID, "error", err)
	}
	seen := map[string]struct{}{}
	var messages []transcript.TranscriptMessage
	agent := "Claude Code"
	var inTok, outTok int64
	var hasTokens bool
	var attribution *transcript.SessionAttribution
	var fallback bool
	var warning string
	var collectedSkillEvents []transcript.SkillEvent

	// The CLI always stores each checkpoint's full.jsonl as the whole session
	// snapshot up to that checkpoint (the per-session transcriptIdentifierAtStart /
	// checkpointTranscriptStart are read-time window markers into that full blob,
	// NOT storage slices — verified against the writer). So the newest contributing
	// checkpoint's blob already holds the entire conversation, and we read only it.
	// Reading the older copies would just re-feed duplicate messages into the
	// id-dedup below — which collapses to nothing useful when the parser can't
	// recover stable message ids (it falls back to random ids), leaving the
	// transcript repeated once per checkpoint. Metadata — tokens summed,
	// attribution/agent latest, skill events collected — still accumulates from
	// every checkpoint regardless of which blobs are parsed.
	//
	// latestOnly (read the newest blob alone) needs only that the set is orderable,
	// so we can identify the newest; a missing created_at leaves the set unorderable,
	// so latestOnly is false and the merge stitches every checkpoint (window-sliced,
	// deduped) as a correctness-preserving fallback.
	ordered, orderable := store.ContribsByRecencyDesc(contribs)
	latestOnly := orderable

	// foldMessages appends a parsed blob's messages into the running set, deduping
	// by id — the shared body of the cumulative and delta stitches, so both agree on
	// dedup. Not concurrency-safe: callers fold in contribution order.
	foldMessages := func(msgs []transcript.TranscriptMessage) {
		for _, m := range msgs {
			if _, dup := seen[m.ID]; dup {
				continue
			}
			seen[m.ID] = struct{}{}
			messages = append(messages, m)
		}
	}

	// resolveBlob reads one checkpoint's full.jsonl (via src) and parses it under the
	// process-wide budget, which reserves the blob's byte ceiling before the read and
	// shrinks to the actual size for the parse (so the read buffer counts too) and
	// releases per call. It touches no shared merge state, so the delta fan-out calls
	// it concurrently; the caller folds the result. readErr is a tolerated per-blob
	// miss the caller logs, distinct from err (a budget shed / cancellation that
	// stops the merge). It is the single ResolveBlob call site — both stitches route
	// their blob reads through it, differing only in the agent they parse with.
	resolveBlob := func(rctx context.Context, cp store.ContributingCheckpointSessions, idx int, agent, identifier string, offset int) ([]transcript.TranscriptMessage, transcript.ParseResult, error, error) {
		return budget.ResolveBlob(rctx, checkpointlayout.MaxTranscriptBytes,
			func(c context.Context) ([]byte, error) { return src(c, cp, idx) },
			agent, identifier, offset)
	}

	// mergeBlob resolves one checkpoint's blob and folds it into the running set,
	// taking the latest fallback/warning. Serial (it mutates the merge state), used
	// by the cumulative branch, which reads newest-first and stops at the first hit;
	// it parses with the final accumulated agent.
	mergeBlob := func(cp store.ContributingCheckpointSessions, idx int, identifier string, offset int) (readErr, err error) {
		msgs, pr, readErr, err := resolveBlob(ctx, cp, idx, agent, identifier, offset)
		if err != nil {
			return nil, err
		}
		if readErr != nil {
			return readErr, nil
		}
		if pr.IsFallback {
			fallback = true
		}
		if pr.Warning != "" {
			warning = pr.Warning
		}
		foldMessages(msgs)
		return nil, nil
	}

	// deltaRead captures one contributing checkpoint's blob-read inputs for the
	// delta-sliced stitch. agent carries forward across checkpoints, so blob i must
	// parse with the agent as of checkpoint i — captured here in contribution order.
	type deltaRead struct {
		cp         store.ContributingCheckpointSessions
		idx        int
		identifier string
		offset     int
		agent      string
	}
	var deltaReads []deltaRead

	for _, cp := range contribs {
		idx := store.SessionIndex(cp.Sessions, sessionID)
		if idx < 0 {
			continue
		}
		meta := cp.Sessions[idx]
		agent = firstNonEmpty(meta.Agent, agent)
		if meta.TokenUsage != nil {
			hasTokens = true
			inTok += meta.TokenUsage.InputTokens
			outTok += meta.TokenUsage.OutputTokens
		}
		if meta.Attribution != nil {
			attribution = storeAttribution(meta.Attribution)
		}
		// Per-checkpoint metadata (including skill events) lives in the sessions
		// JSONB, present even when the transcript blob read fails below.
		if se := transcript.FilterSkillEventsForTranscriptWindow(meta.SkillEvents, derefIntZero(meta.CheckpointTranscriptStart)); len(se) > 0 {
			collectedSkillEvents = append(collectedSkillEvents, se...)
		}
		// The unorderable fallback stitches every checkpoint's window here. The
		// orderable fast path is served after the loop from the newest readable blob
		// alone (it already holds the whole session), so skip per-checkpoint parsing.
		if latestOnly {
			continue
		}
		deltaReads = append(deltaReads, deltaRead{
			cp: cp, idx: idx, identifier: meta.TranscriptIdentifierAtStart,
			offset: derefIntZero(meta.CheckpointTranscriptStart), agent: agent,
		})
	}

	// Read + parse the delta-sliced blobs with bounded concurrency — they are
	// independent entiredb round-trips, and the process-wide budget still bounds the
	// bytes parsed at once — then fold them in contribution order so message dedup
	// and the fallback/warning "last wins" stay identical to a serial stitch.
	if len(deltaReads) > 0 {
		type blobResult struct {
			msgs    []transcript.TranscriptMessage
			pr      transcript.ParseResult
			readErr error
		}
		results := make([]blobResult, len(deltaReads))
		g, gctx := errgroup.WithContext(ctx)
		g.SetLimit(transcriptReadConcurrency)
		for i, rd := range deltaReads {
			i, rd := i, rd
			g.Go(func() error {
				msgs, pr, readErr, err := resolveBlob(gctx, rd.cp, rd.idx, rd.agent, rd.identifier, rd.offset)
				if err != nil {
					return err
				}
				results[i] = blobResult{msgs: msgs, pr: pr, readErr: readErr}
				return nil
			})
		}
		if err := g.Wait(); err != nil {
			return transcript.SessionTranscript{}, readFailed, err
		}
		for i, res := range results {
			if res.readErr != nil {
				noteBlobReadErr(deltaReads[i].cp.CheckpointID, res.readErr)
				continue
			}
			if res.pr.IsFallback {
				fallback = true
			}
			if res.pr.Warning != "" {
				warning = res.pr.Warning
			}
			foldMessages(res.msgs)
		}
	}

	// Orderable: the newest checkpoint's blob is the whole session, so parse just
	// one — whole (identifier="", offset=0), not sliced to its window. Read
	// newest-first and fall back to an older complete copy when a blob is
	// unavailable: a shared viewer's snapshot bundle can lag the live contributing
	// set (errSnapshotMissingCheckpoint), so committing to the single latest id
	// would collapse such a read to an empty transcript instead of serving the
	// most complete copy on hand.
	if latestOnly {
		for _, cp := range ordered {
			idx := store.SessionIndex(cp.Sessions, sessionID)
			if idx < 0 {
				continue
			}
			readErr, err := mergeBlob(cp, idx, "", 0)
			if err != nil {
				return transcript.SessionTranscript{}, readFailed, err
			}
			if readErr != nil {
				noteBlobReadErr(cp.CheckpointID, readErr)
				continue
			}
			break
		}
	}
	skillEvents := transcript.DedupeSkillEvents(collectedSkillEvents)
	messages = transcript.AnnotateMessagesWithSkillEvents(messages, skillEvents)
	if messages == nil {
		messages = []transcript.TranscriptMessage{}
	}
	st := transcript.SessionTranscript{SessionID: sessionID, Agent: agent, Messages: messages, ParsingFallback: fallback, ParsingWarning: warning}
	if len(skillEvents) > 0 {
		st.SkillEvents = skillEvents
	}
	if hasTokens {
		st.TokenUsage = &transcript.SessionTokenUsage{InputTokens: inTok, OutputTokens: outTok}
	}
	st.Attribution = attribution
	return st, readFailed, nil
}
