func sharedSessionSubagents(ctx context.Context, deps *RepoActivityDeps, in *SharedSessionSubagentsInput) (*SessionSubagentsOutput, error) {
	_, sessionID, bundle, err := resolveSharedSnapshot(ctx, deps, in.ShareID)
	if err != nil {
		return nil, err
	}
	var afterStarted time.Time
	var afterID string
	if in.Cursor != "" {
		var ok bool
		afterStarted, afterID, ok = decodeSubagentsCursor(in.Cursor)
		if !ok {
			return nil, huma.Error400BadRequest("invalid cursor")
		}
	}
	start := 0
	if afterID != "" {
		start = len(bundle.Subagents)
		for i, summary := range bundle.Subagents {
			if summary.StartedAt.After(afterStarted) ||
				(summary.StartedAt.Equal(afterStarted) && summary.SubagentID > afterID) {
				start = i
				break
			}
		}
	}
	limit := clampLimit(in.Limit, sessionSubagentsDefaultLimit, sessionSubagentsMaxLimit)
	end := min(start+limit, len(bundle.Subagents))
	out := &SessionSubagentsOutput{}
	out.Body.SessionID = sessionID
	out.Body.Subagents = make([]SubagentSummaryItem, 0, end-start)
	for _, summary := range bundle.Subagents[start:end] {
		out.Body.Subagents = append(out.Body.Subagents, snapshotSubagentSummaryToItem(summary))
	}
	if end < len(bundle.Subagents) && end > start {
		last := bundle.Subagents[end-1]
		cursor := encodeSubagentsCursor(last.StartedAt, last.SubagentID)
		out.Body.NextCursor = &cursor
	}
	return out, nil
}
func sharedSessionSubagentTranscript(ctx context.Context, deps *RepoActivityDeps, in *SharedSessionSubagentTranscriptInput) (*SessionSubagentTranscriptOutput, error) {
	_, _, bundle, err := resolveSharedSnapshot(ctx, deps, in.ShareID)
	if err != nil {
		return nil, err
	}
	var summary *snapshot.SubagentSummary
	for i := range bundle.Subagents {
		if bundle.Subagents[i].SubagentID == in.SubagentID {
			summary = &bundle.Subagents[i]
			break
		}
	}
	if summary == nil {
		return nil, huma.Error404NotFound("not found")
	}
	content, ok := bundle.SubagentTranscripts[in.SubagentID]
	if !ok {
		return nil, huma.Error404NotFound("not found")
	}
	messages, parsed, readErr, budgetErr := deps.TranscriptBudget.ResolveBlob(ctx, checkpointlayout.MaxTranscriptBytes,
		func(context.Context) ([]byte, error) { return content, nil }, summary.Agent, "", 0)
	if budgetErr != nil {
		return nil, parseBudgetError(budgetErr)
	}
	if readErr != nil {
		return nil, huma.Error500InternalServerError("snapshot: child transcript", readErr)
	}
	if messages == nil {
		messages = []transcript.TranscriptMessage{}
	}
	out := &SessionSubagentTranscriptOutput{}
	out.Body.Summary = snapshotSubagentSummaryToItem(*summary)
	out.Body.Transcript = transcript.SessionTranscript{
		SessionID: summary.SubagentID, Agent: summary.Agent, Messages: messages,
		ParsingFallback: parsed.IsFallback, ParsingWarning: parsed.Warning,
	}
	return out, nil
}

