package httpapi

import (
	"encoding/json"
	"net/http"
	"testing"

	"github.com/entirehq/entire-api/internal/store"
)

func TestSubagentReadCompatibilitySurface(t *testing.T) {
	t.Parallel()

	spec := fullSurfaceRouter(t).API.OpenAPI()
	want := map[string]string{
		"/repos/{repo_id}/sessions/{session_id}/subagents":                          "repoSessionSubagents",
		"/repos/{repo_id}/sessions/{session_id}/subagents/{subagent_id}/transcript": "repoSessionSubagentTranscript",
		"/sessions/{share_id}/subagents":                                            "sharedSessionSubagents",
		"/sessions/{share_id}/subagents/{subagent_id}/transcript":                   "sharedSessionSubagentTranscript",
	}
	for route, operationID := range want {
		item := spec.Paths[route]
		if item == nil || item.Get == nil {
			t.Errorf("GET %s is absent from the published API", route)
			continue
		}
		if item.Get.OperationID != operationID {
			t.Errorf("GET %s operationId = %q, want %q", route, item.Get.OperationID, operationID)
		}
		if item.Post != nil || item.Put != nil || item.Patch != nil || item.Delete != nil {
			t.Errorf("%s restored a write operation; compatibility must remain read-only", route)
		}
		if operationID == "repoSessionSubagents" || operationID == "repoSessionSubagentTranscript" {
			if _, ok := item.Get.Responses[http.StatusText(http.StatusBadGateway)]; ok {
				t.Errorf("GET %s publishes a response under the status text instead of status code", route)
			}
			if _, ok := item.Get.Responses["502"]; !ok {
				t.Errorf("GET %s does not publish its 502 read-through failure", route)
			}
		}
	}

	b, err := json.Marshal(sessionToItem(store.Session{}, nil))
	if err != nil {
		t.Fatal(err)
	}
	var item map[string]any
	if err := json.Unmarshal(b, &item); err != nil {
		t.Fatal(err)
	}
	if got, ok := item["subagentCount"]; !ok || got != float64(0) {
		t.Errorf("session list item subagentCount = %v, present=%v; want numeric zero", got, ok)
	}
}
