package httpapi

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"path"
	"sort"
	"strings"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"golang.org/x/sync/errgroup"

	"github.com/entirehq/entire-api/internal/agents"
	"github.com/entirehq/entire-api/internal/checkpointlayout"
	"github.com/entirehq/entire-api/internal/checkpointredact"
	"github.com/entirehq/entire-api/internal/providertranscript"
	"github.com/entirehq/entire-api/internal/repoapi"
	"github.com/entirehq/entire-api/internal/snapshot"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entirehq/entire-api/internal/transcript"
)

// Subagents are read straight from checkpoint artifacts. The CLI materializes
// every subagent a session dispatched into the parent session's checkpoint as
//
//	<checkpoint>/tasks/<tool_use_id>/task.json
//	<checkpoint>/tasks/<tool_use_id>/agent-<agent_id>.jsonl
//
// where tool_use_id is the id of the Task tool call in the parent transcript.
// That id is the whole join: a subagent's SubagentID *is* its tool_use_id, so
// the client attaches it to the parent tool call it already renders. Nothing
// is persisted in the store for this; there is no ingestion, hydration, or
// backfill step.
const (
	sessionSubagentsDefaultLimit = 50
	sessionSubagentsMaxLimit     = 200

	// maxTaskMetadataBytes caps one task.json read; the file is a few hundred
	// bytes of labels and timings.
	maxTaskMetadataBytes = 16 << 10
)

type SessionSubagentsInput struct {
	RepoID    string `path:"repo_id"`
	SessionID string `path:"session_id"`
}

type SessionSubagentTranscriptInput struct {
	RepoID     string `path:"repo_id"`
	SessionID  string `path:"session_id"`
	SubagentID string `path:"subagent_id"`
}

type SubagentSummaryItem struct {
	SubagentID      string  `json:"subagentId"`
	ToolUseID       *string `json:"toolUseId"`
	NativeAgentID   *string `json:"nativeAgentId"`
	Agent           string  `json:"agent"`
	TaskDescription string  `json:"taskDescription"`
	StartedAt       string  `json:"startedAt"`
	LastActivityAt  string  `json:"lastActivityAt"`
	CheckpointCount int64   `json:"checkpointCount"`
}

type SessionSubagentsOutput struct {
	Body struct {
		SessionID  string                `json:"sessionId"`
		Subagents  []SubagentSummaryItem `json:"subagents"`
		NextCursor *string               `json:"nextCursor"`
	}
}

type SessionSubagentTranscriptOutput struct {
	Body struct {
		Summary    SubagentSummaryItem          `json:"summary"`
		Model      *string                      `json:"model"`
		Transcript transcript.SessionTranscript `json:"transcript"`
	}
}

// taskMetadata is the CLI's task.json, restricted to the fields served here.
type taskMetadata struct {
	ToolUseID                   string    `json:"tool_use_id"`
	AgentID                     string    `json:"agent_id"`
	TaskDescription             string    `json:"task_description"`
	StartedAt                   time.Time `json:"started_at"`
	TranscriptUnavailableReason string    `json:"transcript_unavailable_reason"`
}

// checkpointTask is one task.json observed in one contributing checkpoint.
// The same task recurs across checkpoints (each condensation stores the
// transcript-so-far), so summaries aggregate by ToolUseID.
type checkpointTask struct {
	taskMetadata
	Agent          string
	CheckpointID   string
	CapturedAt     time.Time
	RefBacked      bool
	TranscriptPath string // "" when the checkpoint holds no agent-<id>.jsonl
}

func listSessionSubagents(ctx context.Context, deps *RepoActivityDeps, in *SessionSubagentsInput) (*SessionSubagentsOutput, error) {
	storageRepoID, checkpoints, err := sessionTaskCheckpoints(ctx, deps, in.RepoID, in.SessionID)
	if err != nil {
		return nil, err
	}
	tasks, err := readSessionTasks(ctx, deps, in.RepoID, storageRepoID, in.SessionID, checkpoints)
	if err != nil {
		return nil, subagentReadError(err)
	}
	summaries, err := summarizeTasks(ctx, tasks)
	if err != nil {
		return nil, huma.Error500InternalServerError("redact task metadata", err)
	}
	out := &SessionSubagentsOutput{}
	out.Body.SessionID = in.SessionID
	out.Body.Subagents = summaries
	return out, nil
}

func sessionSubagentTranscript(ctx context.Context, deps *RepoActivityDeps, in *SessionSubagentTranscriptInput) (*SessionSubagentTranscriptOutput, error) {
	if !safeTaskSegment(in.SubagentID) {
		return nil, huma.Error404NotFound("subagent transcript not found")
	}
	storageRepoID, checkpoints, err := sessionTaskCheckpoints(ctx, deps, in.RepoID, in.SessionID)
	if err != nil {
		return nil, err
	}
	all, err := readSessionTasks(ctx, deps, in.RepoID, storageRepoID, in.SessionID, checkpoints)
	if err != nil {
		return nil, subagentReadError(err)
	}
	var tasks []checkpointTask
	for _, task := range all {
		if task.ToolUseID == in.SubagentID {
			tasks = append(tasks, task)
		}
	}
	summaries, err := summarizeTasks(ctx, tasks)
	if err != nil {
		return nil, huma.Error500InternalServerError("redact task metadata", err)
	}
	if len(summaries) == 0 {
		return nil, huma.Error404NotFound("subagent transcript not found")
	}
	summary := summaries[0]

	// Newest capture first: every checkpoint stores the transcript-so-far, so
	// the latest one is the most complete. Older copies are the fallback when
	// a blob read fails.
	sort.SliceStable(tasks, func(i, j int) bool { return newerTask(tasks[i], tasks[j]) })
	readCtx, err := deps.storageReadContext(ctx, in.RepoID, storageRepoID)
	if err != nil {
		return nil, err
	}
	client := repoContentClient(readCtx, deps)
	attempted := false
	for _, task := range tasks {
		if task.TranscriptPath == "" {
			continue
		}
		attempted = true
		ref, _ := checkpointlayout.RefAndFolder(task.CheckpointID, task.RefBacked)
		var raw []byte
		messages, parsed, readErr, budgetErr := deps.TranscriptBudget.ResolveBlob(ctx, checkpointlayout.MaxTranscriptBytes,
			func(readContext context.Context) ([]byte, error) {
				var err error
				raw, err = client.RawFile(readContext, deps.RepoAPIBase, storageRepoID, ref, task.TranscriptPath, checkpointlayout.MaxTranscriptBytes)
				return raw, err
			}, summary.Agent, "", 0)
		if budgetErr != nil {
			return nil, parseBudgetError(budgetErr)
		}
		if readErr != nil {
			slog.WarnContext(ctx, "subagent transcript read failed; trying older capture",
				"repo_id", in.RepoID, "session_id", in.SessionID, "subagent_id", in.SubagentID,
				"checkpoint_id", task.CheckpointID, "error", readErr)
			continue
		}
		if messages == nil {
			messages = []transcript.TranscriptMessage{}
		}
		out := &SessionSubagentTranscriptOutput{}
		out.Body.Summary = summary
		if model, err := providertranscript.ExtractModel(ctx, summary.Agent, raw); err != nil {
			slog.WarnContext(ctx, "subagent model extraction failed",
				"repo_id", in.RepoID, "session_id", in.SessionID, "subagent_id", in.SubagentID, "error", err)
		} else if model != "" {
			out.Body.Model = &model
		}
		out.Body.Transcript = transcript.SessionTranscript{
			SessionID: summary.SubagentID, Agent: summary.Agent, Messages: messages,
			ParsingFallback: parsed.IsFallback, ParsingWarning: parsed.Warning,
		}
		return out, nil
	}
	if !attempted {
		// The CLI recorded the task but could not capture its transcript
		// (task.json carries transcript_unavailable_reason).
		return nil, huma.Error404NotFound("subagent transcript not found")
	}
	return nil, huma.Error502BadGateway("subagent transcript unavailable")
}

// sessionTaskCheckpoints resolves the storage repo, confirms the session exists,
// and returns the checkpoints it contributed to.
func sessionTaskCheckpoints(ctx context.Context, deps *RepoActivityDeps, codeRepoID, sessionID string) (string, []store.ContributingCheckpointSessions, error) {
	storageRepoID, err := deps.checkpointStorageRepoID(ctx, codeRepoID)
	if err != nil {
		return "", nil, err
	}
	if _, ok, err := deps.Store.GetSession(ctx, storageRepoID, sessionID); err != nil {
		return "", nil, huma.Error500InternalServerError("store: session", err)
	} else if !ok {
		return "", nil, huma.Error404NotFound("session not found")
	}
	checkpoints, err := deps.Store.ContributingCheckpointSessions(ctx, storageRepoID, sessionID)
	if err != nil {
		return "", nil, huma.Error500InternalServerError("store: contributing checkpoints", err)
	}
	return storageRepoID, checkpoints, nil
}

func subagentReadError(err error) error {
	if errors.Is(err, transcript.ErrBudgetExhausted) {
		return parseBudgetError(err)
	}
	return huma.Error502BadGateway("subagent artifacts unavailable", err)
}

// readSessionTasks lists every task.json under tasks/ in the session's
// contributing checkpoints. tasks/ sits at the checkpoint root, so when a
// checkpoint condensed several sessions at once its tasks are attributed by
// exact tool_use_id match against the parent transcript's tool calls; a
// single-session checkpoint needs no such check. Per-checkpoint read failures
// are skipped and logged; the read fails only when every checkpoint failed.
func readSessionTasks(ctx context.Context, deps *RepoActivityDeps, codeRepoID, storageRepoID, sessionID string, checkpoints []store.ContributingCheckpointSessions) ([]checkpointTask, error) {
	var own []store.ContributingCheckpointSessions
	shared := false
	for _, cp := range checkpoints {
		if store.SessionIndex(cp.Sessions, sessionID) < 0 {
			continue
		}
		own = append(own, cp)
		shared = shared || len(cp.Sessions) > 1
	}
	if len(own) == 0 {
		return nil, nil
	}
	if deps.RepoAPIBase == "" {
		return nil, errors.New("RepoAPIBase empty")
	}
	readCtx, err := deps.storageReadContext(ctx, codeRepoID, storageRepoID)
	if err != nil {
		return nil, err
	}
	client := repoContentClient(readCtx, deps)

	var parentToolCalls map[string]struct{}
	if shared {
		parentToolCalls, err = parentToolCallIDs(ctx, deps, client, codeRepoID, storageRepoID, sessionID, own)
		if err != nil {
			return nil, err
		}
	}

	results := make([][]checkpointTask, len(own))
	errs := make([]error, len(own))
	var group errgroup.Group
	group.SetLimit(transcriptReadConcurrency)
	for i, cp := range own {
		group.Go(func() error {
			results[i], errs[i] = readCheckpointTasks(ctx, client, deps.RepoAPIBase, storageRepoID, sessionID, cp)
			return nil
		})
	}
	_ = group.Wait()

	var tasks []checkpointTask
	var failures []error
	for i, cp := range own {
		if errs[i] != nil {
			failures = append(failures, errs[i])
			continue
		}
		for _, task := range results[i] {
			if len(cp.Sessions) > 1 {
				if _, owned := parentToolCalls[task.ToolUseID]; !owned {
					continue
				}
			}
			tasks = append(tasks, task)
		}
	}
	if len(failures) == len(own) {
		return nil, errors.Join(failures...)
	}
	if len(failures) > 0 {
		slog.WarnContext(ctx, "subagent checkpoint reads partially failed",
			"repo_id", codeRepoID, "session_id", sessionID,
			"checkpoint_count", len(own), "failed_count", len(failures), "error", errors.Join(failures...))
	}
	return tasks, nil
}

// parentToolCallIDs parses the parent session's transcript and returns the ids
// of its tool calls — the set a shared checkpoint's tasks must match. A parent
// that cannot be read yields an empty set, so nothing is attributed by guess.
func parentToolCallIDs(ctx context.Context, deps *RepoActivityDeps, client *repoapi.Client, codeRepoID, storageRepoID, sessionID string, checkpoints []store.ContributingCheckpointSessions) (map[string]struct{}, error) {
	parent, readFailed, err := mergeSessionTranscript(ctx, deps.TranscriptBudget, codeRepoID, sessionID, checkpoints,
		func(readContext context.Context, cp store.ContributingCheckpointSessions, idx int) ([]byte, error) {
			ref, folder := checkpointlayout.RefAndFolder(cp.CheckpointID, cp.RefBacked)
			return client.RawFile(readContext, deps.RepoAPIBase, storageRepoID, ref,
				store.SessionBlobPathAt(cp.Sessions, folder, idx), checkpointlayout.MaxTranscriptBytes)
		})
	if err != nil {
		return nil, err
	}
	if readFailed && len(parent.Messages) == 0 {
		slog.WarnContext(ctx, "parent transcript unreadable; tasks from shared checkpoints are not attributed",
			"repo_id", codeRepoID, "session_id", sessionID)
	}
	ids := make(map[string]struct{})
	for _, message := range parent.Messages {
		for _, call := range message.ToolCalls {
			if call.ID != "" {
				ids[call.ID] = struct{}{}
			}
		}
	}
	return ids, nil
}

// readCheckpointTasks lists one checkpoint's tasks/ subtree and parses every
// task.json in it. A checkpoint without a tasks/ subtree yields nothing.
func readCheckpointTasks(ctx context.Context, client *repoapi.Client, base, repoID, sessionID string, cp store.ContributingCheckpointSessions) ([]checkpointTask, error) {
	ref, folder := checkpointlayout.RefAndFolder(cp.CheckpointID, cp.RefBacked)
	tasksRoot := checkpointlayout.TasksPath(folder)
	entries, truncated, err := client.Tree(ctx, base, repoID, ref, tasksRoot, true)
	if errors.Is(err, repoapi.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read tasks tree %s: %w", cp.CheckpointID, err)
	}
	if truncated || len(entries) > checkpointlayout.MaxTaskEntries {
		return nil, fmt.Errorf("read tasks tree %s: %w", cp.CheckpointID, repoapi.ErrWalkTruncated)
	}

	blobs := make(map[string]struct{}, len(entries))
	var metadataPaths []string
	for _, entry := range entries {
		if entry.Type != "blob" {
			continue
		}
		p := entry.Path
		if !strings.HasPrefix(p, tasksRoot+"/") {
			p = path.Join(tasksRoot, p)
		}
		blobs[p] = struct{}{}
		if path.Base(p) == "task.json" && path.Dir(path.Dir(p)) == tasksRoot {
			metadataPaths = append(metadataPaths, p)
		}
	}
	if len(metadataPaths) == 0 {
		return nil, nil
	}
	sort.Strings(metadataPaths)
	files, err := client.Files(ctx, base, repoID, ref, metadataPaths, maxTaskMetadataBytes)
	if err != nil {
		return nil, fmt.Errorf("read task metadata %s: %w", cp.CheckpointID, err)
	}

	capturedAt := time.Time{}
	if cp.CreatedAt != nil {
		capturedAt = *cp.CreatedAt
	}
	agent := string(agents.Unknown)
	if idx := store.SessionIndex(cp.Sessions, sessionID); idx >= 0 {
		agent = string(agents.GetAgentID(cp.Sessions[idx].Agent))
	}

	tasks := make([]checkpointTask, 0, len(metadataPaths))
	for _, metadataPath := range metadataPaths {
		file := files[metadataPath]
		if file.Status != repoapi.FileStatusOK {
			continue
		}
		var meta taskMetadata
		if json.Unmarshal(file.Content, &meta) != nil {
			continue
		}
		// The directory name is the tool_use_id; a task.json that disagrees, or
		// whose ids could escape the subtree, is not served.
		if meta.ToolUseID != path.Base(path.Dir(metadataPath)) || !safeTaskSegment(meta.ToolUseID) || meta.StartedAt.IsZero() {
			continue
		}
		if meta.AgentID != "" && !safeTaskSegment(meta.AgentID) {
			continue
		}
		task := checkpointTask{taskMetadata: meta, Agent: agent, CheckpointID: cp.CheckpointID, CapturedAt: capturedAt, RefBacked: cp.RefBacked}
		if task.CapturedAt.IsZero() {
			task.CapturedAt = meta.StartedAt
		}
		if meta.AgentID != "" && meta.TranscriptUnavailableReason == "" {
			transcriptPath := path.Join(path.Dir(metadataPath), "agent-"+meta.AgentID+".jsonl")
			if _, ok := blobs[transcriptPath]; ok {
				task.TranscriptPath = transcriptPath
			}
		}
		tasks = append(tasks, task)
	}
	return tasks, nil
}

// summarizeTasks folds per-checkpoint task observations into one summary per
// tool_use_id: labels from the newest capture, started_at from the earliest,
// last activity from the newest, checkpointCount distinct. Task descriptions
// are redacted on the way out — the CLI stores them verbatim.
func summarizeTasks(ctx context.Context, tasks []checkpointTask) ([]SubagentSummaryItem, error) {
	latest := make(map[string]checkpointTask)
	started := make(map[string]time.Time)
	checkpoints := make(map[string]map[string]struct{})
	for _, task := range tasks {
		id := task.ToolUseID
		if cur, ok := latest[id]; !ok || newerTask(task, cur) {
			latest[id] = task
		}
		if first, ok := started[id]; !ok || task.StartedAt.Before(first) {
			started[id] = task.StartedAt
		}
		if checkpoints[id] == nil {
			checkpoints[id] = make(map[string]struct{})
		}
		checkpoints[id][task.CheckpointID] = struct{}{}
	}
	if len(latest) == 0 {
		return []SubagentSummaryItem{}, nil
	}
	redactor, err := checkpointredact.New(nil)
	if err != nil {
		return nil, err
	}
	out := make([]SubagentSummaryItem, 0, len(latest))
	for id, task := range latest {
		description, err := redactor.String(ctx, task.TaskDescription)
		if err != nil {
			return nil, err
		}
		toolUseID := id
		item := SubagentSummaryItem{
			SubagentID: id, ToolUseID: &toolUseID, Agent: task.Agent, TaskDescription: description,
			StartedAt: isoTime(started[id]), LastActivityAt: isoTime(task.CapturedAt),
			CheckpointCount: int64(len(checkpoints[id])),
		}
		if task.AgentID != "" {
			agentID := task.AgentID
			item.NativeAgentID = &agentID
		}
		out = append(out, item)
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].StartedAt == out[j].StartedAt {
			return out[i].SubagentID < out[j].SubagentID
		}
		return out[i].StartedAt < out[j].StartedAt
	})
	return out, nil
}

// newerTask orders captures of the same task, newest first, with the
// checkpoint id as a deterministic tiebreak.
func newerTask(a, b checkpointTask) bool {
	if a.CapturedAt.Equal(b.CapturedAt) {
		return a.CheckpointID > b.CheckpointID
	}
	return a.CapturedAt.After(b.CapturedAt)
}

// safeTaskSegment accepts an id usable as a single path segment under tasks/.
func safeTaskSegment(value string) bool {
	return value != "" && value != "." && value != ".." && !strings.ContainsAny(value, `/\`) && path.Clean(value) == value
}

// --- shared (snapshot) sessions ---------------------------------------------
//
// A public session share carries its subagents inside the immutable snapshot
// bundle; these routes page through that bundle and never touch checkpoints.

type subagentsCursor struct {
	StartedAt  string `json:"startedAt"`
	SubagentID string `json:"subagentId"`
}

func encodeSubagentsCursor(startedAt time.Time, subagentID string) string {
	b, _ := json.Marshal(subagentsCursor{StartedAt: startedAt.UTC().Format(time.RFC3339Nano), SubagentID: subagentID})
	return base64.RawURLEncoding.EncodeToString(b)
}

func decodeSubagentsCursor(cursor string) (time.Time, string, bool) {
	b, err := base64.RawURLEncoding.DecodeString(cursor)
	if err != nil {
		return time.Time{}, "", false
	}
	var decoded subagentsCursor
	if err := json.Unmarshal(b, &decoded); err != nil || strings.TrimSpace(decoded.SubagentID) == "" {
		return time.Time{}, "", false
	}
	startedAt, err := time.Parse(time.RFC3339Nano, decoded.StartedAt)
	if err != nil || startedAt.IsZero() {
		return time.Time{}, "", false
	}
	return startedAt, decoded.SubagentID, true
}

func snapshotSubagentSummaryToItem(summary snapshot.SubagentSummary) SubagentSummaryItem {
	return SubagentSummaryItem{
		SubagentID: summary.SubagentID, ToolUseID: summary.ToolUseID,
		NativeAgentID: summary.NativeAgentID, Agent: summary.Agent,
		TaskDescription: summary.TaskDescription, StartedAt: isoTime(summary.StartedAt),
		LastActivityAt: isoTime(summary.LastActivityAt), CheckpointCount: summary.CheckpointCount,
	}
}

func sharedSessionSubagents(ctx context.Context, deps *RepoActivityDeps, in *SharedSessionSubagentsInput) (*SessionSubagentsOutput, error) {
	_, sessionID, bundle, err := resolveSharedSnapshot(ctx, deps, in.ShareID)
	if err != nil {
		return nil, err
	}
	var afterStarted time.Time
	var afterID string
	if in.Cursor != "" {
		var ok bool
		afterStarted, afterID, ok = decodeSubagentsCursor(in.Cursor)
		if !ok {
			return nil, huma.Error400BadRequest("invalid cursor")
		}
	}
	start := 0
	if afterID != "" {
		start = len(bundle.Subagents)
		for i, summary := range bundle.Subagents {
			if summary.StartedAt.After(afterStarted) ||
				(summary.StartedAt.Equal(afterStarted) && summary.SubagentID > afterID) {
				start = i
				break
			}
		}
	}
	limit := clampLimit(in.Limit, sessionSubagentsDefaultLimit, sessionSubagentsMaxLimit)
	end := min(start+limit, len(bundle.Subagents))
	out := &SessionSubagentsOutput{}
	out.Body.SessionID = sessionID
	out.Body.Subagents = make([]SubagentSummaryItem, 0, end-start)
	for _, summary := range bundle.Subagents[start:end] {
		out.Body.Subagents = append(out.Body.Subagents, snapshotSubagentSummaryToItem(summary))
	}
	if end < len(bundle.Subagents) && end > start {
		last := bundle.Subagents[end-1]
		cursor := encodeSubagentsCursor(last.StartedAt, last.SubagentID)
		out.Body.NextCursor = &cursor
	}
	return out, nil
}

func sharedSessionSubagentTranscript(ctx context.Context, deps *RepoActivityDeps, in *SharedSessionSubagentTranscriptInput) (*SessionSubagentTranscriptOutput, error) {
	_, _, bundle, err := resolveSharedSnapshot(ctx, deps, in.ShareID)
	if err != nil {
		return nil, err
	}
	var summary *snapshot.SubagentSummary
	for i := range bundle.Subagents {
		if bundle.Subagents[i].SubagentID == in.SubagentID {
			summary = &bundle.Subagents[i]
			break
		}
	}
	if summary == nil {
		return nil, huma.Error404NotFound("not found")
	}
	content, ok := bundle.SubagentTranscripts[in.SubagentID]
	if !ok {
		return nil, huma.Error404NotFound("not found")
	}
	messages, parsed, readErr, budgetErr := deps.TranscriptBudget.ResolveBlob(ctx, checkpointlayout.MaxTranscriptBytes,
		func(context.Context) ([]byte, error) { return content, nil }, summary.Agent, "", 0)
	if budgetErr != nil {
		return nil, parseBudgetError(budgetErr)
	}
	if readErr != nil {
		return nil, huma.Error500InternalServerError("snapshot: child transcript", readErr)
	}
	if messages == nil {
		messages = []transcript.TranscriptMessage{}
	}
	out := &SessionSubagentTranscriptOutput{}
	out.Body.Summary = snapshotSubagentSummaryToItem(*summary)
	out.Body.Transcript = transcript.SessionTranscript{
		SessionID: summary.SubagentID, Agent: summary.Agent, Messages: messages,
		ParsingFallback: parsed.IsFallback, ParsingWarning: parsed.Warning,
	}
	return out, nil
}

