package httpapi

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/entirehq/entire-api/internal/repoapi"
	"github.com/entirehq/entire-api/internal/store"
)

type fakeTaskArtifactReader struct {
	entries   []repoapi.TreeEntry
	truncated bool
	treeErr   error
	files     map[string]repoapi.FileResult
}

func (f fakeTaskArtifactReader) Tree(context.Context, string, string, string, string, bool) ([]repoapi.TreeEntry, bool, error) {
	return f.entries, f.truncated, f.treeErr
}

func (f fakeTaskArtifactReader) Files(_ context.Context, _, _, _ string, paths []string, _ int64) (map[string]repoapi.FileResult, error) {
	out := make(map[string]repoapi.FileResult, len(paths))
	for _, p := range paths {
		out[p] = f.files[p]
	}
	return out, nil
}

func okFile(path, content string) repoapi.FileResult {
	return repoapi.FileResult{Path: path, Status: repoapi.FileStatusOK, Content: []byte(content), Size: int64(len(content))}
}

func testCheckpoint(id string, capturedAt time.Time, sessions ...string) store.ContributingCheckpointSessions {
	cp := store.ContributingCheckpointSessions{CheckpointID: id, RefBacked: true, CreatedAt: &capturedAt}
	for _, s := range sessions {
		cp.Sessions = append(cp.Sessions, store.SessionInfo{SessionID: s, Agent: "Codex"})
	}
	return cp
}

func TestReadCheckpointTasksParsesTaskLayout(t *testing.T) {
	t.Parallel()

	capturedAt := time.Date(2026, 8, 25, 12, 0, 0, 0, time.UTC)
	reader := fakeTaskArtifactReader{
		entries: []repoapi.TreeEntry{
			{Path: "tasks/task-1/task.json", Type: "blob"},
			{Path: "tasks/task-1/agent-child-1.jsonl", Type: "blob"},
			// Transcript never captured: no agent file, reason recorded.
			{Path: "tasks/task-2/task.json", Type: "blob"},
			// Directory name disagrees with tool_use_id: not served.
			{Path: "tasks/task-3/task.json", Type: "blob"},
			// Not a task record.
			{Path: "tasks/task-1/todo.json", Type: "blob"},
		},
		files: map[string]repoapi.FileResult{
			"tasks/task-1/task.json": okFile("tasks/task-1/task.json",
				`{"tool_use_id":"task-1","agent_id":"child-1","task_description":"inspect the parser","started_at":"2026-08-25T11:59:00Z"}`),
			"tasks/task-2/task.json": okFile("tasks/task-2/task.json",
				`{"tool_use_id":"task-2","started_at":"2026-08-25T11:58:00Z","transcript_unavailable_reason":"transcript unreadable"}`),
			"tasks/task-3/task.json": okFile("tasks/task-3/task.json",
				`{"tool_use_id":"other","agent_id":"x","started_at":"2026-08-25T11:58:00Z"}`),
		},
	}
	tasks, err := readCheckpointTasks(context.Background(), reader, "https://repo.test", "repo-1", "parent-1",
		testCheckpoint("01TESTCHECKPOINT0000000000", capturedAt, "parent-1"))
	if err != nil {
		t.Fatal(err)
	}
	if len(tasks) != 2 {
		t.Fatalf("tasks = %+v, want task-1 and task-2", tasks)
	}
	got := tasks[0]
	if got.ToolUseID != "task-1" || got.AgentID != "child-1" || got.Agent != "codex" || got.TaskDescription != "inspect the parser" {
		t.Fatalf("task-1 = %+v", got)
	}
	if got.TranscriptPath != "tasks/task-1/agent-child-1.jsonl" || !got.CapturedAt.Equal(capturedAt) {
		t.Fatalf("task-1 source = %+v", got)
	}
	if tasks[1].ToolUseID != "task-2" || tasks[1].TranscriptPath != "" {
		t.Fatalf("task-2 = %+v, want no transcript", tasks[1])
	}
}

func TestReadCheckpointTasksMissingSubtreeIsEmpty(t *testing.T) {
	t.Parallel()

	tasks, err := readCheckpointTasks(context.Background(), fakeTaskArtifactReader{treeErr: repoapi.ErrNotFound},
		"https://repo.test", "repo-1", "parent-1", testCheckpoint("cp", time.Now(), "parent-1"))
	if err != nil || len(tasks) != 0 {
		t.Fatalf("tasks, err = %v, %v; want none", tasks, err)
	}
}

func TestReadCheckpointTasksRejectsTruncatedTree(t *testing.T) {
	t.Parallel()

	_, err := readCheckpointTasks(context.Background(), fakeTaskArtifactReader{truncated: true},
		"https://repo.test", "repo-1", "parent-1", testCheckpoint("cp", time.Now(), "parent-1"))
	if !errors.Is(err, repoapi.ErrWalkTruncated) {
		t.Fatalf("err = %v, want ErrWalkTruncated", err)
	}
}

func TestSummarizeTasksAggregatesAcrossCheckpoints(t *testing.T) {
	t.Parallel()

	early := time.Date(2026, 8, 25, 12, 0, 0, 0, time.UTC)
	late := early.Add(time.Hour)
	task := func(cpID string, capturedAt time.Time, description string) checkpointTask {
		return checkpointTask{
			taskMetadata: taskMetadata{ToolUseID: "task-1", AgentID: "child-1", TaskDescription: description, StartedAt: early},
			Agent:        "claude", CheckpointID: cpID, CapturedAt: capturedAt,
		}
	}
	summaries, err := summarizeTasks(context.Background(), []checkpointTask{
		task("cp-late", late, "final description"),
		task("cp-early", early, "early description"),
		{taskMetadata: taskMetadata{ToolUseID: "task-0", StartedAt: early.Add(-time.Minute)}, Agent: "claude", CheckpointID: "cp-early", CapturedAt: early},
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(summaries) != 2 || summaries[0].SubagentID != "task-0" || summaries[1].SubagentID != "task-1" {
		t.Fatalf("summaries = %+v, want task-0 then task-1 by started_at", summaries)
	}
	got := summaries[1]
	if got.TaskDescription != "final description" || got.CheckpointCount != 2 {
		t.Fatalf("task-1 = %+v, want newest labels over two checkpoints", got)
	}
	if got.StartedAt != isoTime(early) || got.LastActivityAt != isoTime(late) {
		t.Fatalf("task-1 timing = %+v", got)
	}
	if got.ToolUseID == nil || *got.ToolUseID != "task-1" || got.NativeAgentID == nil || *got.NativeAgentID != "child-1" {
		t.Fatalf("task-1 ids = %+v", got)
	}
	if summaries[0].NativeAgentID != nil {
		t.Fatalf("task-0 without agent_id must have nil nativeAgentId: %+v", summaries[0])
	}
}

func TestSummarizeTasksRedactsDescriptions(t *testing.T) {
	t.Parallel()

	summaries, err := summarizeTasks(context.Background(), []checkpointTask{{
		taskMetadata: taskMetadata{ToolUseID: "task-1", StartedAt: time.Now(),
			TaskDescription: "use token REDACTED to fetch"},
		CheckpointID: "cp",
	}})
	if err != nil {
		t.Fatal(err)
	}
	if got := summaries[0].TaskDescription; got == "" || containsAny(got, "REDACTED") {
		t.Fatalf("description = %q, want the token redacted", got)
	}
}

func containsAny(s string, parts ...string) bool {
	for _, p := range parts {
		if len(p) > 0 && len(s) >= len(p) {
			for i := 0; i+len(p) <= len(s); i++ {
				if s[i:i+len(p)] == p {
					return true
				}
			}
		}
	}
	return false
}

func TestSafeTaskSegment(t *testing.T) {
	t.Parallel()

	for _, ok := range []string{"toolu_01ABC", "task-1", "a.b"} {
		if !safeTaskSegment(ok) {
			t.Errorf("%q rejected", ok)
		}
	}
	for _, bad := range []string{"", ".", "..", "a/b", `a\b`, "./a", "a/"} {
		if safeTaskSegment(bad) {
			t.Errorf("%q accepted", bad)
		}
	}
}

