import type { ReactNode } from "react"

import type { ToolCall } from "@/data/sessions/sessionTranscript"
import { DiffViewer } from "@/domains/platform/components/diff"

export type ToolCategory = "File edits" | "Bash" | "Read" | "Skills" | "Entire" | "Other"

export const TOOL_CATEGORIES: ToolCategory[] = [
  "File edits",
  "Bash",
  "Read",
  "Skills",
  "Entire",
  "Other",
]

const CODE_TOOLS = new Set(["Edit", "Write", "NotebookEdit"])

// Command runners that wrap another binary (`npx entire …`, `sudo entire …`),
// skipped when looking for the actual command head in a shell segment.
const COMMAND_RUNNERS = new Set([
  "npx",
  "pnpm",
  "pnpx",
  "bunx",
  "yarn",
  "dlx",
  "sudo",
  "env",
  "time",
  "command",
])

/**
 * True when a Bash command invokes the Entire CLI (`entire …`). Handles
 * separators (`&&`, `||`, `;`, `|`, newlines), leading env-var assignments
 * (`FOO=bar entire …`), wrappers (`npx entire …`), and path-qualified binaries
 * (`./bin/entire`, `node_modules/.bin/entire`).
 */
export function isEntireCliCommand(command: string): boolean {
  for (const segment of command.split(/\|\||&&|[;\n|&]/)) {
    const tokens = segment.trim().split(/\s+/).filter(Boolean)
    let i = 0
    while (
      i < tokens.length &&
      (/^[A-Za-z_][A-Za-z0-9_]*=/.test(tokens[i]) || COMMAND_RUNNERS.has(tokens[i]))
    ) {
      i++
    }
    const head = tokens[i]
    if (head && head.split("/").pop() === "entire") return true
  }
  return false
}

// Entire-authored skills, mirrored from https://github.com/entireio/skills.
// Add new entries here as the published skill set grows.
const ENTIRE_SKILLS = new Set([
  "explain",
  "recall",
  "replay",
  "review",
  "search",
  "session-crosslink",
  "session-handoff",
  "session-to-skill",
  "teach",
  "using-entire",
  "what-happened",
])

/** The skill name a `Skill` tool call invoked, from its input or sidecar annotation. */
function getSkillName(
  toolCall: Pick<ToolCall, "name" | "input" | "skillInvocation">,
): string | null {
  if (toolCall.name !== "Skill") return null
  const skill = toolCall.input.skill
  return typeof skill === "string" ? skill : (toolCall.skillInvocation?.skillName ?? null)
}

/**
 * True when a tool call invokes Entire's own tooling: the `entire` CLI via Bash,
 * or one of the Entire-authored skills (see `ENTIRE_SKILLS`).
 */
export function isEntireToolCall(
  toolCall: Pick<ToolCall, "name" | "input" | "skillInvocation">,
): boolean {
  const { name, input } = toolCall
  if (name === "Bash") return typeof input.command === "string" && isEntireCliCommand(input.command)
  const skillName = getSkillName(toolCall)
  return skillName !== null && ENTIRE_SKILLS.has(skillName)
}

/** Primary display category for a tool call, by tool name. */
export function getToolCategory({ name }: Pick<ToolCall, "name">): ToolCategory {
  if (CODE_TOOLS.has(name)) return "File edits"
  if (name === "Bash") return "Bash"
  if (name === "Read" || name === "Grep" || name === "Glob") return "Read"
  if (name === "Skill") return "Skills"
  return "Other"
}

/**
 * Every category a tool call belongs to. A call always has its one primary
 * category (by tool name); Entire tooling (the `entire` CLI, Entire-authored
 * skills) *additionally* surfaces under the "Entire" section, so such calls
 * show up both in their natural category and Entire.
 */
export function getToolCategories(
  toolCall: Pick<ToolCall, "name" | "input" | "skillInvocation">,
): ToolCategory[] {
  const primary = getToolCategory(toolCall)
  return isEntireToolCall(toolCall) ? [primary, "Entire"] : [primary]
}

/** One-line summary of a tool call, for showing next to the tool name in a list. */
export function getToolCallSummary(toolCall: ToolCall): string | null {
  const { name, input } = toolCall
  switch (name) {
    case "Read":
    case "Edit":
    case "Write":
      return typeof input.file_path === "string" ? (input.file_path.split("/").pop() ?? null) : null
    case "Bash":
      return typeof input.command === "string" ? input.command.slice(0, 60) : null
    case "Grep":
    case "Glob":
      return typeof input.pattern === "string" ? input.pattern : null
    case "WebSearch":
      return typeof input.query === "string" ? input.query : null
    case "WebFetch":
      return typeof input.url === "string" ? input.url : null
    case "Skill":
      return typeof input.skill === "string"
        ? input.skill
        : (toolCall.skillInvocation?.skillName ?? null)
    default:
      return null
  }
}

/** True when the tool call has a result worth rendering (error, file, matches, output). */
export function hasDisplayableResult(toolCall: ToolCall): boolean {
  const { result } = toolCall
  if (!result) return false
  if (result.error) return true
  if (result.file) return true
  if (result.matchCount !== undefined) return true
  if (result.output?.trim()) return true
  return false
}

/** Format a tool-call input map for display inside a `<pre>`. */
function formatInput(input: Record<string, unknown>): string {
  return Object.entries(input)
    .map(([key, value]) => {
      const displayValue = typeof value === "string" ? value : JSON.stringify(value, null, 2)
      return `${key}: ${displayValue}`
    })
    .join("\n")
}

/** Format a tool-call result into a display string (error / file / matches / output / raw). */
function formatToolResult(toolCall: ToolCall): string {
  const { result } = toolCall
  if (!result) return ""
  if (result.error) return result.error
  if (result.file) {
    return `${result.file.filePath}${result.file.numLines ? ` (${result.file.numLines} lines)` : ""}`
  }
  if (result.matchCount !== undefined) {
    return `Found ${result.matchCount} match${result.matchCount !== 1 ? "es" : ""}`
  }
  if (result.output?.trim()) return result.output
  return JSON.stringify(result, null, 2)
}

/** Build a minimal unified-diff patch string from two file contents. */
function createDiffPatch(oldString: string, newString: string): string {
  const oldLines = oldString.split("\n")
  const newLines = newString.split("\n")
  const lines: string[] = []
  lines.push(`@@ -1,${oldLines.length} +1,${newLines.length} @@`)
  for (const line of oldLines) lines.push(`-${line}`)
  for (const line of newLines) lines.push(`+${line}`)
  return lines.join("\n")
}

/** Trailing path segment, or the whole string when there's no separator. */
function getFileName(filePath: string): string {
  return filePath.split("/").pop() || filePath
}

/** Small uppercase section heading inside an expanded tool-call detail block. */
function SectionLabel({ children }: { children: ReactNode }) {
  return <span className="mb-1.5 block font-mono text-xs text-muted uppercase">{children}</span>
}

/**
 * Detail pane rendered when a tool call row is expanded. Shows the diff view
 * for `Edit` calls with `old_string`/`new_string`; otherwise shows the arguments
 * and (when available) the formatted result.
 */
export function ToolCallDetail({ toolCall }: { toolCall: ToolCall }) {
  const isEditDiff =
    toolCall.name === "Edit" && !!toolCall.input.old_string && !!toolCall.input.new_string
  const showResult =
    !!toolCall.result && hasDisplayableResult(toolCall) && (!isEditDiff || !!toolCall.result.error)

  return (
    <div className={isEditDiff ? "bg-raised/40" : "space-y-3 bg-raised/40 px-3 pb-3"}>
      {isEditDiff ? (
        <DiffViewer
          patch={createDiffPatch(
            toolCall.input.old_string as string,
            toolCall.input.new_string as string,
          )}
          filename={getFileName((toolCall.input.file_path as string) ?? "")}
          showChrome={false}
        />
      ) : (
        <div className="pt-3">
          <SectionLabel>Arguments</SectionLabel>
          <pre className="overflow-x-auto rounded-xl border border-default bg-sunken p-2 font-mono text-xs text-muted">
            {formatInput(toolCall.input)}
          </pre>
        </div>
      )}
      {showResult && (
        <div className={isEditDiff ? "p-3" : ""}>
          <SectionLabel>Result</SectionLabel>
          <pre className="overflow-x-auto rounded-xl border border-default bg-sunken p-2 font-mono text-xs text-muted">
            {formatToolResult(toolCall)}
          </pre>
        </div>
      )}
    </div>
  )
}

