function TurnCard({
  turn,
  authorUsername,
  filters,
  showHiddenSummaries,
  suppressHiddenUserIndicator = false,
  areAllToolCallsExpanded,
  expandedHidden,
  onToggleHidden,
  getCheckpointHref,
}: {
  turn: TurnGroup
  authorUsername?: string
  filters: FilterState
  showHiddenSummaries: boolean
  suppressHiddenUserIndicator?: boolean
  areAllToolCallsExpanded: boolean
  expandedHidden: Set<string>
  onToggleHidden: (id: string) => void
  getCheckpointHref?: GetCheckpointHref
}) {
  const { inlineAttachments } = useSessionTimeline()
  const { turnNumber, userMessage, assistantMessages, agent, checkpoints } = turn

  const innerHiddenId = `turn-${turnNumber}-hidden`
  const innerHiddenExpanded = expandedHidden.has(innerHiddenId)

  // When the inner placeholder is expanded, render this turn's content as if
  // filters were fully on. Counts below are computed against the real filter
  // set, so the placeholder always reflects what's being suppressed.
  const effectiveFilters = innerHiddenExpanded ? ALL_FILTERS_ON : filters

  // Intermediate rows (anything that isn't the turn's final content-bearing
  // response) hide their response text when Intermediate steps is off, but
  // tool calls remain independently controlled by the Tool calls/category
  // filters so enabling Tool calls can reveal tools-only rows.
  const finalResponseIdx = findFinalResponseIndex(assistantMessages)
  const renderedAssistantMessages = assistantMessages
    .map((message, index) => ({ message, index }))
    .filter(({ message, index }) => {
      const isIntermediate = finalResponseIdx >= 0 && index !== finalResponseIdx
      const content = message.content?.trim()
      const hasVisibleContent =
        effectiveFilters.responses &&
        !!content &&
        (!isIntermediate || effectiveFilters.intermediateSteps)
      const hasVisibleTools = hasVisibleToolCalls(message.toolCalls, effectiveFilters)
      const hasInlineAttachments = messageHasInlineAttachment(message, inlineAttachments)
      return hasVisibleContent || hasVisibleTools || hasInlineAttachments
    })

  const hasUserPayload = hasUserMessagePayload(userMessage)
  const showUser = filters.prompts && !!userMessage && hasUserPayload
  const visibleCheckpoints = effectiveFilters.checkpoints ? checkpoints : []

  // Count hidden parts against the real filters: messages whose row is fully
  // suppressed, responses suppressed on still-visible rows, tool calls filtered
  // out (including per-category toggles), and hidden inner checkpoints.
  const {
    hiddenMessages,
    hiddenResponses,
    hiddenToolCalls,
    hiddenCheckpoints: hiddenCheckpointsCount,
  } = computeTurnHiddenCounts(userMessage, assistantMessages, checkpoints, filters)
  const userPromptHidden = !showUser && !!userMessage && hasUserPayload
  const hiddenUserMessage = !suppressHiddenUserIndicator && userPromptHidden
  const hiddenUserId = `turn-${turnNumber}-hidden-user`
  const hiddenUserExpanded = expandedHidden.has(hiddenUserId)
  const trailingHiddenMessages = Math.max(0, hiddenMessages - (userPromptHidden ? 1 : 0))
  const trailingTotalHidden =
    trailingHiddenMessages + hiddenResponses + hiddenToolCalls + hiddenCheckpointsCount

  // Hidden prompt indicators belong at the start of the turn, where the prompt
  // would have rendered. Everything else (hidden assistant rows/tool calls/
  // checkpoints) still collapses after the visible assistant content.
  const showInnerHidden = trailingTotalHidden > 0

  if (!showUser && renderedAssistantMessages.length === 0 && visibleCheckpoints.length === 0) {
    return null
  }

  // Footer meta: duration from the user prompt to the last assistant reply,
  // plus a count of tool calls made in the turn. Tokens aren't available
  // per-turn (the transcript only exposes session-level totals).
  const lastAssistantTs = assistantMessages[assistantMessages.length - 1]?.timestamp ?? null
  const turnDuration =
    userMessage?.timestamp && lastAssistantTs
      ? formatCompactDuration(userMessage.timestamp, lastAssistantTs)
      : null
  const turnToolCount = assistantMessages.reduce((sum, m) => sum + (m.toolCalls?.length ?? 0), 0)

  return (
    <>
      {showHiddenSummaries && hiddenUserMessage && userMessage && (
        <>
          <HiddenItemsRow
            label={buildHiddenLabel({ messages: 1 })}
            expanded={hiddenUserExpanded}
            onToggle={() => onToggleHidden(hiddenUserId)}
          />
          {hiddenUserExpanded && (
            <UserTurnRow
              userMessage={userMessage}
              authorUsername={authorUsername}
              turnDuration={turnDuration}
              turnToolCount={turnToolCount}
            />
          )}
        </>
      )}

      {showUser && userMessage && (
        <UserTurnRow
          userMessage={userMessage}
          authorUsername={authorUsername}
          turnDuration={turnDuration}
          turnToolCount={turnToolCount}
        />
      )}

      {showHiddenSummaries && showInnerHidden && (
        <HiddenItemsRow
          label={buildHiddenLabel({
            messages: trailingHiddenMessages,
            responses: hiddenResponses,
            toolCalls: hiddenToolCalls,
            checkpoints: hiddenCheckpointsCount,
          })}
          expanded={innerHiddenExpanded}
          onToggle={() => onToggleHidden(innerHiddenId)}
        />
      )}

      {renderedAssistantMessages.map(({ message: msg, index }) => {
        const isIntermediate = finalResponseIdx >= 0 && index !== finalResponseIdx
        const content = msg.content?.trim() || null
        const showContent =
          !!content &&
          effectiveFilters.responses &&
          (!isIntermediate || effectiveFilters.intermediateSteps)
        const toolCalls = msg.toolCalls ?? []
        const visibleToolCalls = effectiveFilters.toolCalls
          ? toolCalls.filter((tc) =>
              getToolCategories(tc).some((c) => effectiveFilters.toolCategories[c]),
            )
          : []
        const visibleToolCallIds = new Set(visibleToolCalls.map((toolCall) => toolCall.id))
        const hasToolAttachments = toolCalls.some(
          (toolCall) => inlineAttachments?.byToolCallId.has(toolCall.id) === true,
        )
        return (
          <TimelineRow
            key={msg.id}
            id={`timeline-${msg.id}`}
            icon={
              <EntryAvatarLink entryId={msg.id} label="Link to this message">
                <AgentAvatar agent={agent} className="size-6" />
              </EntryAvatarLink>
            }
          >
            <div className="pl-3">
              {showContent && (
                <div className="text-default">
                  <MarkdownContent>{content}</MarkdownContent>
                </div>
              )}
              {(visibleToolCalls.length > 0 || hasToolAttachments) && (
                <InlineToolList
                  toolCalls={toolCalls}
                  visibleToolCallIds={visibleToolCallIds}
                  hasContentAbove={showContent}
                  areAllExpanded={areAllToolCallsExpanded}
                />
              )}
              {inlineAttachments?.byMessageId.get(msg.id)}
            </div>
          </TimelineRow>
        )
      })}

      {visibleCheckpoints.map((cp) => (
        <TimelineRow
          key={`cp-${cp.commitSha}`}
          id={`timeline-${cp.checkpointId}`}
          align="center"
          icon={<CheckpointRailDot />}
        >
          <CheckpointCard checkpoint={cp} getCheckpointHref={getCheckpointHref} />
        </TimelineRow>
      ))}
    </>
  )
}

