function InlineToolList({
  toolCalls,
  visibleToolCallIds,
  hasContentAbove,
  areAllExpanded,
}: {
  toolCalls: ToolCall[]
  visibleToolCallIds: Set<string>
  hasContentAbove: boolean
  areAllExpanded: boolean
}) {
  const { inlineAttachments } = useSessionTimeline()
  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set())
  const [prevAreAllExpanded, setPrevAreAllExpanded] = useState(areAllExpanded)
  if (prevAreAllExpanded !== areAllExpanded) {
    setPrevAreAllExpanded(areAllExpanded)
    setExpandedRows(
      areAllExpanded ? new Set(toolCalls.map((_, index) => index)) : new Set<number>(),
    )
  }

  const toggleRow = (index: number) => {
    setExpandedRows((prev) => {
      const next = new Set(prev)
      if (next.has(index)) next.delete(index)
      else next.add(index)
      return next
    })
  }

  return (
    <div className={`flex flex-col gap-px ${hasContentAbove ? "mt-3" : ""}`}>
      {toolCalls.map((toolCall, index) => (
        <InlineToolCall
          key={toolCall.id}
          toolCall={toolCall}
          visible={visibleToolCallIds.has(toolCall.id)}
          expanded={expandedRows.has(index)}
          onToggle={() => toggleRow(index)}
          attachment={inlineAttachments?.byToolCallId.get(toolCall.id)}
        />
      ))}
    </div>
  )
}

function InlineToolCall({
  toolCall,
  visible,
  expanded,
  onToggle,
  attachment,
}: {
  toolCall: ToolCall
  visible: boolean
  expanded: boolean
  onToggle: () => void
  attachment?: ReactNode
}) {
  const summary = getToolCallSummary(toolCall)
  const hasDetail =
    (toolCall.name === "Edit" && !!toolCall.input.old_string && !!toolCall.input.new_string) ||
    Object.keys(toolCall.input).length > 0 ||
    hasDisplayableResult(toolCall)

  const isError = toolCall.result?.type === "error" || !!toolCall.result?.error

  if (!visible && !attachment) return null

  return (
    <div
      id={visible ? `timeline-${toolCall.id}` : undefined}
      data-parent-tool-call-id={toolCall.id}
      className={
        visible
          ? `scroll-mt-[calc(var(--global-header-height)+1rem)] overflow-hidden rounded-xl ${HASH_TARGET_HIGHLIGHT}`
          : undefined
      }
    >
      <button
        hidden={!visible}
        type="button"
        onClick={() => hasDetail && onToggle()}
        className="grid w-full cursor-pointer grid-cols-[5rem_1fr_auto_auto] items-center gap-3 px-3 py-2 text-left hover:bg-hover"
      >
        <span className={`font-mono text-xs ${getToolCategoryTextClass(toolCall)}`}>
          {toolCall.name}
        </span>
        <span className="truncate font-mono text-xs text-muted">{summary ?? ""}</span>
        {isError ? (
          <Badge className="bg-red-500/15 text-red-700 dark:bg-red-500/20 dark:text-red-400">
            Failed
          </Badge>
        ) : (
          <span />
        )}
        {hasDetail ? (
          <ChevronDown
            className={`size-3.5 shrink-0 text-muted transition ${expanded ? "rotate-180" : ""}`}
          />
        ) : (
          <div className="size-3.5 shrink-0" />
        )}
      </button>
      {visible && expanded && hasDetail && <ToolCallDetail toolCall={toolCall} />}
      {attachment}
    </div>
  )
}

