function downloadTextFile(filename: string, contents: string, type: string) {
  const blob = new Blob([contents], { type })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename
  document.body.append(link)
  link.click()
  link.remove()
  URL.revokeObjectURL(url)
}

interface DownloadTranscriptButtonProps {
  org: string
  repo: string
  sessionId: string
  data: CompleteSessionTranscriptResponse
  messages: TranscriptMessage[]
}

function DownloadTranscriptButton({
  org,
  repo,
  sessionId,
  data,
  messages,
}: DownloadTranscriptButtonProps) {
  const handleDownload = useCallback(
    (format: TranscriptDownloadFormat) => {
      const filename = getDownloadFilename(org, repo, sessionId, format)
      const contents =
        format === "markdown"
          ? buildTranscriptMarkdown(data, messages)
          : buildTranscriptJsonl(messages)
      const type =
        format === "markdown" ? "text/markdown;charset=utf-8" : "application/x-ndjson;charset=utf-8"

      downloadTextFile(filename, contents, type)
    },
    [data, messages, org, repo, sessionId],
  )

  return (
    <Dropdown>
      <DropdownTrigger asChild>
        <Button size="small" className="whitespace-nowrap">
          Download
          <ChevronDown className="size-4 text-muted" strokeWidth={1.5} />
        </Button>
      </DropdownTrigger>
      <DropdownContent width="narrow">
        <DropdownItem onClick={() => handleDownload("markdown")}>Markdown</DropdownItem>
        <DropdownItem onClick={() => handleDownload("jsonl")}>JSONL</DropdownItem>
      </DropdownContent>
    </Dropdown>
  )
}

export function SessionDetailPage({
  provider,
  org,
  repo,
  sessionId,
  onTimelineTargetChange,
  relativeTimeReferenceMs,
}: SessionDetailPageProps) {
  const queryClient = useQueryClient()
  const sessionDetailFilterPreference = useSessionDetailFilterPreference()

  const { data, isLoading, isError } = useSessionTranscriptQuery(org, repo, sessionId, { provider })
  const isTranscriptPending = data?.status === "pending"
  const isTranscriptUnavailable = data?.status === "failed"
  const completeData =
    data && (data.status === "complete" || data.status === undefined) ? data : null
  const subagentAccess = useMemo(
    () => ({ provider, org, repo, sessionId }),
    [org, provider, repo, sessionId],
  )
  const subagentsQuery = useSessionSubagentsQuery(subagentAccess, completeData !== null)
  const subagents = useMemo(
    () => subagentsQuery.data?.pages.flatMap((page) => page.subagents) ?? [],
    [subagentsQuery.data?.pages],
  )
  const canSeeCheckpointData = completeData?.viewer.canSeeCheckpointData ?? true
  const permissionsQuery = useRepositoryPermissionsQuery(
    org,
    repo,
    provider === "gh" && completeData?.viewer.canEdit === true && canSeeCheckpointData,
  )
  const canManageSession =
    provider === "et"
      ? completeData?.viewer.canEdit === true
      : permissionsQuery.data?.canAdmin === true
  const sessionTranscriptQueryKey = useMemo(
    () => sessionTranscriptQueryOptions(org, repo, sessionId, provider).queryKey,
    [org, provider, repo, sessionId],
  )
  const sessionListQueryKey = useMemo(
    () =>
      getApiV1CacheByOrgByRepoSessionsInfiniteQueryKey({
        path: { org, repo },
        query: { provider },
      }),
    [org, provider, repo],
  )
  // Mutate both names together so the reset affordance (gated on customName)
  // stays in sync: a rename sets the override, a reset clears it.
  const setCachedSessionName = useCallback(
    (displayName: string, customName: string | null) => {
      queryClient.setQueryData<SessionTranscriptResponse>(sessionTranscriptQueryKey, (current) => {
        if (!current || !("session" in current)) return current
        return {
          ...current,
          session: { ...current.session, displayName, customName },
        }
      })
    },
    [queryClient, sessionTranscriptQueryKey],
  )
  const updateDisplayNameMutation = useMutation({
    mutationFn: (displayName: string | null) =>
      updateSessionDisplayName(org, repo, sessionId, displayName, provider),
    onMutate: async (displayName) => {
      await queryClient.cancelQueries({ queryKey: sessionTranscriptQueryKey, exact: true })
      const previous =
        queryClient.getQueryData<SessionTranscriptResponse>(sessionTranscriptQueryKey)
      // Optimistic for renames only — the new name is also the override. A reset
      // (null) has no client-known resolved name, so it waits for onSuccess.
      if (displayName !== null) setCachedSessionName(displayName, displayName)
      return { previous }
    },
    onError: (_error, _displayName, context) => {
      if (context?.previous) {
        queryClient.setQueryData(sessionTranscriptQueryKey, context.previous)
      }
    },
    onSuccess: ({ displayName }, variables) => {
      // A rename's resolved name is the override; a reset (null) clears it.
      setCachedSessionName(displayName, variables === null ? null : displayName)
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: sessionListQueryKey }),
  })

  const transcriptSessions = completeData?.sessions
  const sessionCheckpoints = completeData?.checkpoints
  const parentModel = completeData?.session.model ?? null
  const orderedMessages = useMemo(
    () => (transcriptSessions ? buildOrderedSessionMessages(transcriptSessions) : []),
    [transcriptSessions],
  )
  const timelineCheckpoints = useMemo(
    () => (sessionCheckpoints ? mapSessionEnvelopeCheckpoints(sessionCheckpoints) : []),
    [sessionCheckpoints],
  )
  const subagentPlacement = useMemo(
    () => placeSubagentsInTimeline(subagents, orderedMessages),
    [orderedMessages, subagents],
  )
  const inlineSubagentAttachments = useMemo(
    () => ({
      byToolCallId: new Map(
        [...subagentPlacement.byToolCallId].map(([toolCallId, children]) => [
          toolCallId,
          <SessionSubagentCards
            key={`subagents-tool-${toolCallId}`}
            access={subagentAccess}
            subagents={children}
            parentModel={parentModel}
          />,
        ]),
      ),
      byMessageId: new Map(
        [...subagentPlacement.byMessageId].map(([messageId, children]) => [
          messageId,
          <SessionSubagentCards
            key={`subagents-message-${messageId}`}
            access={subagentAccess}
            subagents={children}
            parentModel={parentModel}
          />,
        ]),
      ),
    }),
    [parentModel, subagentAccess, subagentPlacement.byMessageId, subagentPlacement.byToolCallId],
  )
  if (isLoading || isTranscriptPending) {
    return <SessionDetailSkeleton />
  }

  if (isError || !data) {
    return <NotFoundContent />
  }

  if (isTranscriptUnavailable) {
    return (
      <div className="mx-auto max-w-5xl py-12 text-center text-muted">
        Transcript data is unavailable for this session.
      </div>
    )
  }

  if (!completeData) {
    return <NotFoundContent />
  }

  const firstCheckpoint = completeData.checkpoints[0]
  const authorUsername = firstCheckpoint?.authorUsername ?? ""
  // Public repositories still get a Share affordance, but their sessions are
  // already public so the dialog is informational and only copies this page's
  // URL. Where a share grant is meaningful (private sources, or public sources
  // with separate private checkpoint storage), retain the existing permission
  // gates for changing visibility.
  const shareToggleApplicable =
    completeData.repo.shareToggleApplicable ?? completeData.repo.isPrivate
  const isAlwaysPublic = !completeData.repo.isPrivate && !shareToggleApplicable
  const canToggleShare =
    completeData.viewer.canEdit && shareToggleApplicable && canSeeCheckpointData
  const showShareDialog = isAlwaysPublic || canToggleShare

  // `publicSharingEnabled` is the per-repo opt-in for *private* repos. Public
  // source repos don't have it (the flag isn't toggleable on a public repo),
  // so for the public+private-storage case we treat "sharing is available"
  // as always true at the repo level — storage-repo membership is the gate
  // that matters there, and `showShareDialog` already requires it. Without
  // this, the dialog would render its "sharing is disabled at repo level"
  // branch for public repos and the toggle would be unreachable in the UI
  // even though POST /share would accept it.
  const repoSharingEnabledForDialog = completeData.repo.isPrivate
    ? completeData.repo.publicSharingEnabled
    : true
  const canAccessCommit = canSeeCheckpointData || !completeData.repo.isPrivate
  const getCheckpointHref = canAccessCommit
    ? (commitSha: string) =>
        `${providerPathPrefix(provider)}/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/commit/${encodeURIComponent(commitSha)}`
    : undefined

  return (
    <SessionTimelineView
      sessionId={sessionId}
      title={getSessionTitle(completeData.session)}
      prompt={completeData.session.prompt}
      titleBadge={completeData.session.isPublic ? <PublicSessionBadge /> : undefined}
      titleEdit={
        canManageSession && canSeeCheckpointData
          ? {
              onSave: (nextDisplayName) => updateDisplayNameMutation.mutate(nextDisplayName),
              disabled: updateDisplayNameMutation.isPending,
              maxLength: 200,
              editLabel: "Edit session display name",
            }
          : undefined
      }
      titleReset={
        canManageSession && canSeeCheckpointData && completeData.session.customName != null
          ? {
              onReset: () => updateDisplayNameMutation.mutate(null),
              disabled: updateDisplayNameMutation.isPending,
              label: "Reset to auto-generated session name",
            }
          : undefined
      }
      agent={completeData.session.agent}
      model={completeData.session.model}
      createdAt={completeData.session.createdAt}
      onTimelineTargetChange={onTimelineTargetChange}
      messages={orderedMessages}
      checkpoints={timelineCheckpoints}
      checkpointCount={completeData.session.checkpointCount}
      tokenUsage={completeData.tokenUsage}
      isTranscriptLoading={false}
      authorUsername={authorUsername}
      authorSlot={
        <span className="flex items-center gap-1.5">
          <GitHubAvatar username={authorUsername || undefined} className="size-5" />
          {authorUsername || "Unknown author"}
        </span>
      }
      actionsSlot={
        <>
          {showShareDialog && (
            <ShareSessionDialog
              provider={provider}
              org={org}
              repo={repo}
              sessionId={sessionId}
              isPublic={completeData.session.isPublic}
              repoSharingEnabled={repoSharingEnabledForDialog}
              isAlwaysPublic={isAlwaysPublic}
              initialShareId={completeData.session.shareId ?? null}
              initialCell={completeData.cell ?? null}
            />
          )}
          <DownloadTranscriptButton
            org={org}
            repo={repo}
            sessionId={sessionId}
            data={completeData}
            messages={orderedMessages}
          />
        </>
      }
      getCheckpointHref={getCheckpointHref}
      filterDefaults={sessionDetailFilterPreference.defaultFilters}
      onSaveFilterDefaults={
        sessionDetailFilterPreference.canSaveDefaultFilters
          ? sessionDetailFilterPreference.saveDefaultFilters
          : undefined
      }
      isSavingFilterDefaults={sessionDetailFilterPreference.isSavingDefaultFilters}
      filterDefaultsSaveStatus={sessionDetailFilterPreference.saveDefaultFiltersStatus}
      showRuntimePromptsFilter
      relativeTimeReferenceMs={relativeTimeReferenceMs}
      inlineAttachments={inlineSubagentAttachments}
      afterTimeline={
        <>
          {subagentPlacement.trailing.length > 0 ? (
            <SessionSubagentCards
              access={subagentAccess}
              subagents={subagentPlacement.trailing}
              parentModel={parentModel}
            />
          ) : null}
          <SessionSubagentsStatus
            isLoading={subagentsQuery.isPending}
            isError={subagentsQuery.isError}
            onRetry={() => void subagentsQuery.refetch()}
            hasMore={subagentsQuery.hasNextPage === true}
            isLoadingMore={subagentsQuery.isFetchingNextPage}
            onLoadMore={() => void subagentsQuery.fetchNextPage()}
          />
        </>
      }
    />
  )
}

