import { useQuery } from "@tanstack/react-query"

import type { RepoProvider } from "@/data/repositories/repositoryProvider"
import {
  getApiV1CacheByOrgByRepoSessionBySessionIdSubagentsBySubagentIdTranscriptOptions,
  getApiV1CacheByOrgByRepoSessionBySessionIdSubagentsOptions,
} from "@/gen/api-sdk/react-query.gen"
import type {
  GetApiV1CacheByOrgByRepoSessionBySessionIdSubagentsBySubagentIdTranscriptResponse,
  GetApiV1CacheByOrgByRepoSessionBySessionIdSubagentsResponse,
} from "@/gen/api-sdk/types.gen"

import type { TranscriptMessage } from "./sessionTranscript"

export type SubagentSummary =
  GetApiV1CacheByOrgByRepoSessionBySessionIdSubagentsResponse["subagents"][number]

export interface SessionSubagentAccess {
  provider: RepoProvider
  org: string
  repo: string
  sessionId: string
}

export interface SubagentTranscript {
  summary: SubagentSummary
  model: string | null
  agent: string
  messages: TranscriptMessage[]
  parsingWarning?: string
}

/**
 * Split a session's captured subagents into the ones whose id is a tool call
 * in the parent transcript (rendered inside that Task row) and the rest. The
 * CLI keys a subagent by its Task tool call id, so a miss means the agent
 * records subagents under its own id (Codex) or the launching call was not
 * captured; those still get listed after the timeline.
 */
export function splitSubagentsByToolCall(
  subagents: readonly SubagentSummary[],
  messages: readonly TranscriptMessage[],
): { byToolCallId: Map<string, SubagentSummary>; unattached: SubagentSummary[] } {
  const toolCallIds = new Set(
    messages.flatMap((message) => (message.toolCalls ?? []).map((toolCall) => toolCall.id)),
  )
  const byToolCallId = new Map<string, SubagentSummary>()
  const unattached: SubagentSummary[] = []
  for (const summary of subagents) {
    if (toolCallIds.has(summary.subagentId)) byToolCallId.set(summary.subagentId, summary)
    else unattached.push(summary)
  }
  return { byToolCallId, unattached }
}

export function useSessionSubagentsQuery(access: SessionSubagentAccess, enabled: boolean) {
  return useQuery({
    ...getApiV1CacheByOrgByRepoSessionBySessionIdSubagentsOptions({
      path: access,
      query: { provider: access.provider },
    }),
    enabled,
    select: (data) => data.subagents,
  })
}

function toSubagentTranscript(
  data: GetApiV1CacheByOrgByRepoSessionBySessionIdSubagentsBySubagentIdTranscriptResponse,
): SubagentTranscript {
  return {
    summary: data.summary,
    model: data.model,
    agent: data.transcript.agent,
    // The BFF proxies the transcript untyped, exactly like the parent
    // session transcript; entire-api renders both with the same parser.
    messages: data.transcript.messages as TranscriptMessage[],
    parsingWarning: data.transcript.parsingWarning,
  }
}

export function useSubagentTranscriptQuery(
  access: SessionSubagentAccess,
  subagentId: string,
  enabled: boolean,
) {
  return useQuery({
    ...getApiV1CacheByOrgByRepoSessionBySessionIdSubagentsBySubagentIdTranscriptOptions({
      path: { ...access, subagentId },
      query: { provider: access.provider },
    }),
    enabled,
    select: toSubagentTranscript,
  })
}

