/** Model identity for "is the child on a different model" — case and the
 *  `[1m]` context-window suffix don't make it a different model. */
function modelIdentity(model: string | null | undefined): string | null {
  const normalized = model
    ?.trim()
    .replace(/\[[^\]]+\]$/, "")
    .toLowerCase()
  return normalized || null
}

/**
 * A captured subagent's transcript, fetched when its Task row is expanded and
 * rendered with the same message and tool-call blocks as the parent. No per-
 * message avatar: the subagent runs the parent's agent, and the model is named
 * only when it differs from the parent's.
 */
function SubagentTranscriptPanel({
  access,
  summary,
}: {
  access: SessionSubagentAccess
  summary: SubagentSummary
}) {
  const { model: parentModel } = useSessionTimeline()
  const query = useSubagentTranscriptQuery(access, summary.subagentId, true)
  const childModel = query.data?.model ?? null
  const showModel = !!childModel && modelIdentity(childModel) !== modelIdentity(parentModel)

  return (
    <div className="space-y-3 bg-raised/40 px-3 pb-3" data-subagent-transcript={summary.subagentId}>
      <div className="flex flex-wrap items-center gap-x-2 pt-3 font-mono text-xs text-muted">
        <span className="uppercase">Subagent</span>
        {showModel && <span>· {formatModel(childModel)}</span>}
        <span>
          · {summary.checkpointCount} {summary.checkpointCount === 1 ? "checkpoint" : "checkpoints"}
        </span>
        {query.data?.parsingWarning && <span>· {query.data.parsingWarning}</span>}
      </div>
      {query.isPending ? (
        <p className="text-xs text-muted">Loading transcript…</p>
      ) : query.isError ? (
        <div className="flex items-center justify-between gap-3 text-xs text-muted">
          <span>Transcript unavailable.</span>
          <Button size="small" onClick={() => void query.refetch()}>
            Retry
          </Button>
        </div>
      ) : query.data.messages.length === 0 ? (
        <p className="text-xs text-muted">Empty transcript.</p>
      ) : (
        <div className="space-y-3 border-l border-subtle pl-3">
          {query.data.messages.map((message) => (
            <SubagentMessage key={message.id} message={message} />
          ))}
        </div>
      )}
    </div>
  )
}

function SubagentMessage({ message }: { message: TranscriptMessage }) {
  const content = message.content?.trim() || null
  const toolCalls = message.toolCalls ?? []
  if (!content && toolCalls.length === 0) return null
  if (message.role === "user") {
    return content ? (
      <div className="rounded-xl bg-sunken px-3 py-2 text-sm text-muted">
        <MarkdownContent>{content}</MarkdownContent>
      </div>
    ) : null
  }
  return (
    <div>
      {content && (
        <div className="text-sm text-default">
          <MarkdownContent>{content}</MarkdownContent>
        </div>
      )}
      {toolCalls.length > 0 && (
        <InlineToolList toolCalls={toolCalls} hasContentAbove={!!content} areAllExpanded={false} />
      )}
    </div>
  )
}

/**
 * Subagents the CLI captured for this session whose id is not a tool call in
 * the transcript (agents that key subagents by their own id, or a launch the
 * transcript never recorded). Rendered after the timeline so they stay
 * reachable; a matched subagent lives inside its Task row instead.
 */
export function UnattachedSubagentList({ subagents }: { subagents: SubagentSummary[] }) {
  const { subagents: session } = useSessionTimeline()
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  if (!session || subagents.length === 0) return null
  const toggle = (id: string) =>
    setExpanded((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  return (
    <section className="mt-6" data-unattached-subagents>
      <p className="mb-2 font-mono text-xs text-muted uppercase">Subagents</p>
      <div className="flex flex-col gap-px overflow-hidden rounded-xl">
        {subagents.map((summary) => (
          <div key={summary.subagentId}>
            <button
              type="button"
              onClick={() => toggle(summary.subagentId)}
              className="grid w-full cursor-pointer grid-cols-[5rem_1fr_auto] items-center gap-3 px-3 py-2 text-left hover:bg-hover"
            >
              <span className="font-mono text-xs text-muted">Subagent</span>
              <span className="truncate font-mono text-xs text-muted">
                {summary.taskDescription?.trim() || summary.subagentId}
              </span>
              <ChevronDown
                className={`size-3.5 shrink-0 text-muted transition ${expanded.has(summary.subagentId) ? "rotate-180" : ""}`}
              />
            </button>
            {expanded.has(summary.subagentId) && (
              <SubagentTranscriptPanel access={session.access} summary={summary} />
            )}
          </div>
        ))}
      </div>
    </section>
  )
}

